Object.assign(window.__SYN,{"c:弦+细+紧": {"o": "弦细紧脉总以寒凝气滞、阳虚血少为纲。弦主肝郁气滞，紧主寒主痛，细主血少阳衰，三象合见，多示寒邪内凝、气机壅塞、营血不足之病机。其具体所主，或为寒凝疼痛，或为虚寒阳衰，或为肝郁气滞，或为血虚痰饮，然总不离“寒”与“虚”两端。寒凝则气滞，气滞则痛；阳虚则寒生，血少则细。诸类之间，寒凝为因，气滞为果，虚寒为本，痰饮为标，相互交织。故临床见弦细紧脉，当辨其寒之轻重、虚之微甚、气滞之部位，以温通、补虚、疏肝、化痰为治，不可一概而论。", "c": [{"name": "主寒凝", "desc": "紧脉主寒，弦细紧并见多示寒邪内凝、阳气被遏。如感受金凉、胸痹头痛，心腹结痛，寒中肝经吐血，寒客厥阴头痛，寒中厥阴胁痛，寒凝于内逼阳于外，皆以紧为寒凝之征。"}, {"name": "主痛", "desc": "弦紧主痛，气血凝滞不通则痛。如产后腹痛拒按，心腹结痛，脘胁作痛，左胁痛甚，巅顶腰背疼，皆因寒凝气滞、脉络拘急而痛，脉弦紧为痛征。"}, {"name": "主虚寒", "desc": "细为血少阳衰，弦紧为寒，合见主虚寒之证。如劳伤吐血、诸虚不足，阳气不摄，脏气沉寒、腑阳衰，绝少阳和之气，少阴水寒凌心，阳衰阴盛，皆以细紧弦示阳虚寒凝。"}, {"name": "主肝郁", "desc": "弦为肝脉，主气机郁滞。如肝郁饮停、厥阴克阳明，十年瘕气肝郁血滞，浊阴上攻胸痛，肝亢克土、气滞水停，血不养肝、邪亢侮中，肝郁气滞血瘀，皆以弦细紧示肝郁不达。"}, {"name": "主血虚", "desc": "细为营血不足，弦紧为寒凝气结。如产后营血已伤，形体羸瘦、气血不足，失精亡血，营液内耗，血不养肝，血去肝虚，皆以细脉示阴血亏虚，弦紧示虚寒凝滞。"}, {"name": "主痰饮", "desc": "弦主饮，紧主寒，细为阳衰。如内饮招外风，瘰疬结核、痰凝络脉，积湿生痰、新感寒邪，呕哕痰涎，中寒痰饮，皆以弦细紧示寒饮内结、痰凝气滞。"}, {"name": "主气滞", "desc": "弦紧主气机郁滞、寒凝收引。如气机窒塞，寒凝气滞，气机郁滞，寒邪阻滞气机，气滞下陷，气结血涩，皆以弦紧示气滞不通，细为兼虚。"}], "n": {"主寒凝": 14, "主痛": 1, "主虚寒": 11, "主肝郁": 3, "主血虚": 3, "主痰饮": 1, "主气滞": 2}, "a": {"486": "主痛", "5218": "主肝郁", "5307": "主虚寒", "5309": "主虚寒", "5311": "主虚寒", "5314": "主虚寒", "5318": "主虚寒", "5345": "主虚寒", "5363": "主寒凝", "5374": "主寒凝", "5440": "主寒凝", "5624": "主寒凝", "5637": "主寒凝", "5690": "主气滞", "5840": "主寒凝", "6567": "主血虚", "6713": "主寒凝", "6726": "主肝郁", "7009": "主血虚", "8713": "主气滞", "10685": "主寒凝", "16071": "主虚寒", "16077": "主虚寒", "16091": "主虚寒", "16101": "主寒凝", "16102": "主肝郁", "16104": "主寒凝", "16114": "主寒凝", "16122": "主虚寒", "16139": "主寒凝", "16143": "主寒凝", "16151": "主寒凝", "16213": "主血虚", "16237": "主痰饮", "16244": "主虚寒"}, "t": 35, "np": 0}, "c:弦+细+软": {"o": "弦细软脉总属虚实夹杂之象：弦应肝木，主气郁、饮停、肝亢；细为阴血不足；软为气弱、湿滞。三象合见，总以正虚为本、郁滞为标。其主病机可归纳为虚（气阴两虚）、湿（暑湿内蕴）、肝郁（肝木偏亢）、饮（痰饮内停）、郁热（郁久化热）、脾虚（脾运不健）六类。诸类之间常相互兼夹：虚为根本，或气虚及阳、或阴亏及血；虚则脾运不健而生湿，湿聚成饮；肝郁则木旺克土，脾虚湿滞；郁久又可化热。故弦细软脉多示本虚标实、虚实夹杂之候，常见于暑湿、湿温、痰饮、肝郁、虚劳等病，治当兼顾虚实，不可偏执。", "c": [{"name": "主虚（气阴两虚）", "desc": "弦细软脉中细为阴血不足、软为气弱不任，合见气阴两虚。原文如「细为阴虚，软则气弱」「六脉弦细而软……体质本弱、阳虚不充」「软细为气液两亏」等，皆以细软示正气亏虚，或劳倦伤气、或病后气血未充，故主虚。"}, {"name": "主湿（暑湿内蕴）", "desc": "软脉主湿，弦细软并见常为暑湿或湿温内蕴。原文「弦细为虚为暑，而软为湿」「固属暑湿」「湿温毒重」等，以软示湿滞、弦细示暑湿伤阴，湿性黏滞故脉软，暑湿内伏则脉弦细而软。"}, {"name": "主肝郁（肝木偏亢）", "desc": "弦脉应肝，弦细软中弦象主肝气郁结或肝木偏亢。原文「弦主气郁」「弦者，肝偏亢也」「肝郁不舒」「肝木侮中」等，以弦示肝郁气滞、木旺克土，细软则兼见阴血不足或脾虚，故脉弦细软。"}, {"name": "主饮（痰饮内停）", "desc": "弦为饮邪内动，细软为阳虚气弱，合见阳虚夹饮。原文「弦为饮邪内动」「弦为饮停」「阳虚夹饮」等，以弦示饮邪上逆、痰浊内盛，细软示阳气不充、脾虚失运，故脉弦细软主痰饮内停。"}, {"name": "主郁热（郁久化热）", "desc": "气机郁久生热，脉见弦软而细。原文「气机多郁，郁久生热」「肝郁化火」「湿滞化热」等，以弦示气郁、软细示阴血不足，郁热内扰则脉象弦细软中或略带数，故主郁热内蕴。"}, {"name": "主脾虚（脾运不健）", "desc": "软脉主气虚，弦细软并见常示脾气已虚、运化迟钝。原文「脾气已虚」「脾阳不振」「脾运迟钝」等，以软示中气不足、细示阴血亏少、弦示木郁乘脾，故脉弦细软主脾虚失运、湿随气滞。"}], "n": {"主虚（气阴两虚）": 4, "主湿（暑湿内蕴）": 6, "主肝郁（肝木偏亢）": 3, "主饮（痰饮内停）": 2, "主郁热（郁久化热）": 2, "主脾虚（脾运不健）": 1}, "a": {"4186": "主湿（暑湿内蕴）", "4187": "主湿（暑湿内蕴）", "4312": "主脾虚（脾运不健）", "5664": "主饮（痰饮内停）", "9113": "主虚（气阴两虚）", "9524": "主饮（痰饮内停）", "9736": "主虚（气阴两虚）", "9761": "主虚（气阴两虚）", "9791": "主肝郁（肝木偏亢）", "10063": "主肝郁（肝木偏亢）", "10503": "主虚（气阴两虚）", "10506": "主肝郁（肝木偏亢）", "13232": "主湿（暑湿内蕴）", "13419": "主湿（暑湿内蕴）", "13449": "主郁热（郁久化热）", "13834": "主湿（暑湿内蕴）", "14536": "主湿（暑湿内蕴）", "16464": "主郁热（郁久化热）"}, "t": 18, "np": 0}, "c:细+虚": {"o": "虚细脉总以虚为本，主气血阴阳亏虚，脉道不充。其虚可涉气、血、阴、阳，病位可在心、脾、肾、肝。虚细无力多主气血两虚或阳气衰微；细而兼数多主阴亏虚火；虚细而弦多主虚中夹实、肝郁风动；虚细见于久病、疮疡后期多主正虚邪恋。各类之间相互关联：气血两虚为基本病机，阴血亏虚、虚火内扰常相兼为患；阳虚寒凝、脾肾两虚多由气虚发展而来；心肾不交为阴虚及阳、水火失济之变；正虚邪恋则为虚体受邪、虚实夹杂之候。总以虚损为核心，或兼邪、或化火、或及阳，然脉象始终以虚细为底色。", "c": [{"name": "主气血两虚", "desc": "虚细脉为气血不足之典型。虚主气亏，细主血少，脉道不充。原文如'脉虚细无力'伴形神萎顿、面色无华、脓水清稀等，皆气血两虚之征。气血亏虚，不能充脉养神，故脉来虚细。"}, {"name": "主阴血亏虚", "desc": "细脉主营血不足，虚为阴分亏耗。原文见'脉形虚细'而咳血、盗汗、舌红少苔，或'细而虚'伴痉厥神昏，皆阴血亏虚、脉道失充之象。阴血不足，不能充盈脉道，故脉细而虚。"}, {"name": "主虚火内扰", "desc": "虚细而数，或虚细兼弦数，为阴亏阳浮、虚火内动。原文如'左脉虚数'、'脉虚细数'，症见咽燥、溺赤、火升轰热，皆阴不制阳、虚热内生。虚火扰于内，故脉数而细。"}, {"name": "主阳虚寒凝", "desc": "虚细无力，或沉细而迟，为阳气衰微、阴寒内盛。原文如'六脉虚细'伴四肢冰冷、虚汗、腹胀坚急，或'脉虚细无神'而神思疲倦，皆阳气不能温运，阴寒凝结，脉道鼓动无力。"}, {"name": "主正虚邪恋", "desc": "虚细脉见于久病、疮疡、湿温后期，正虚而余邪未清。原文如'脉虚细，舌滑白'、'湿热犹存'，或'脉虚细'而寒湿郁络，皆气血已伤，邪气留恋，虚实夹杂，脉象虚细而兼他象。"}, {"name": "主心肾不交", "desc": "虚细脉见于心脉、肾脉，为水火不济、心肾不交。原文如'心脉微数代散，肾脉虚细'，或'心脉、命门脉俱虚细无力'，症见失眠、游魂、心悸，皆肾水亏虚不能上济，心火不能下降，脉道不充。"}, {"name": "主脾肾两虚", "desc": "虚细脉见于脾肺肾部，为先后天俱伤。原文如'脾肺脉虚细无力，肾脉濡弱'，或'脉虚细'而便泻、腰酸、带下，皆脾虚运化失职，肾虚固摄无权，气血生化不足，脉道不充。"}], "n": {"主气血两虚": 43, "主阴血亏虚": 33, "主虚火内扰": 1, "主阳虚寒凝": 7, "主正虚邪恋": 8, "主心肾不交": 7, "主脾肾两虚": 11}, "a": {"9": "主气血两虚", "313": "主气血两虚", "356": "主气血两虚", "645": "主气血两虚", "706": "主气血两虚", "758": "主气血两虚", "841": "主阴血亏虚", "1595": "主气血两虚", "2093": "主气血两虚", "2739": "主气血两虚", "4942": "主阴血亏虚", "7173": "主阴血亏虚", "7501": "主阴血亏虚", "7510": "主阴血亏虚", "7511": "主阴血亏虚", "7513": "主阴血亏虚", "7516": "主阴血亏虚", "10466": "主气血两虚", "10544": "主阴血亏虚", "10870": "主阴血亏虚", "10918": "主正虚邪恋", "10930": "主气血两虚", "11690": "主阴血亏虚", "11736": "主阴血亏虚", "11947": "主气血两虚", "12076": "主脾肾两虚", "12084": "主气血两虚", "12085": "主心肾不交", "12092": "主脾肾两虚", "12128": "主气血两虚", "12131": "主阳虚寒凝", "12151": "主脾肾两虚", "12177": "主气血两虚", "12204": "主气血两虚", "12210": "主气血两虚", "12226": "主气血两虚", "12227": "主气血两虚", "12243": "主阳虚寒凝", "12244": "主气血两虚", "12253": "主正虚邪恋", "12263": "主气血两虚", "12271": "主脾肾两虚", "12274": "主气血两虚", "12294": "主心肾不交", "12295": "主心肾不交", "12470": "主阴血亏虚", "12829": "主正虚邪恋", "13069": "主阴血亏虚", "13650": "主阳虚寒凝", "13728": "主阴血亏虚", "13772": "主阴血亏虚", "13953": "主气血两虚", "13960": "主阴血亏虚", "14067": "主阴血亏虚", "14076": "主阴血亏虚", "14151": "主阴血亏虚", "14158": "主阴血亏虚", "14361": "主阴血亏虚", "14775": "主阳虚寒凝", "14835": "主阴血亏虚", "14851": "主阴血亏虚", "14854": "主阴血亏虚", "15311": "主心肾不交", "15324": "主气血两虚", "15353": "主虚火内扰", "15417": "主正虚邪恋", "15461": "主正虚邪恋", "16115": "主气血两虚", "16185": "主阳虚寒凝", "16397": "主阳虚寒凝", "16742": "主正虚邪恋", "16755": "主脾肾两虚", "16815": "主气血两虚", "16833": "主阴血亏虚", "16836": "主气血两虚", "16861": "主气血两虚", "16862": "主气血两虚", "16863": "主气血两虚", "16866": "主气血两虚", "16867": "主心肾不交", "16873": "主气血两虚", "16878": "主气血两虚", "16928": "主脾肾两虚", "16958": "主脾肾两虚", "16960": "主脾肾两虚", "16963": "主心肾不交", "16965": "主心肾不交", "16967": "主脾肾两虚", "16985": "主正虚邪恋", "16986": "主气血两虚", "16996": "主阴血亏虚", "16998": "主气血两虚", "16999": "主气血两虚", "17007": "主阴血亏虚", "17016": "主阴血亏虚", "17039": "主气血两虚", "17055": "主阴血亏虚", "17084": "主阴血亏虚", "17164": "主脾肾两虚", "17173": "主气血两虚", "18204": "主正虚邪恋", "18556": "主阳虚寒凝", "19233": "主阴血亏虚", "21148": "主阴血亏虚", "21805": "主气血两虚", "21824": "主气血两虚", "22934": "主气血两虚", "25018": "主气血两虚", "25019": "主气血两虚", "25461": "主脾肾两虚"}, "t": 110, "np": 0}, "c:弱+软": {"o": "软弱脉总属虚象，以气血不足、阳气不振为基本病机，脉道失充、鼓动无力故脉来软弱。其主病虽繁，约分六类：气血两虚为总纲，脾虚湿困、阳虚阴损、脏腑亏虚皆虚损之具体表现；气虚不摄为虚而失固之变；虚中夹邪则为正虚邪恋之兼证。各类之间相互关联：气血虚可致脏腑亏，脏腑虚可生湿、可及阳，气虚不摄又可加重气血虚；而虚中夹邪者，必以正虚为本，邪恋为标。故临床见软弱脉，首辨虚之所在与兼夹，总以扶正为要，不可妄攻。", "c": [{"name": "主气血两虚", "desc": "软弱脉为气血不足之征，脉道失充、鼓动无力。原文多称“气血亏”“气血大虚”“气血两亏”，如腋疽溃后脉软弱、产后气血大亏脉软弱无力、六脉软弱如游丝等，皆因气血耗伤，不能充盈脉道，故脉来软弱。"}, {"name": "主脾虚湿困", "desc": "脾主肌肉、运化水湿，脾虚则营卫不足、湿邪内困。原文见“脉形软弱”伴肌肉暗消、脘痞纳少、力乏嗜卧，或“右脉软弱”主脾经不足、湿气有余，或引脉诀“软而弱者，湿家里恙”，皆脾虚失运、湿浊内停之象。"}, {"name": "主阳虚阴损", "desc": "软弱脉亦主阳气虚衰、阴损及阳。如积劳内伤咳血气喘脉来软弱，为阴损及阳、防其虚脱；尺部软弱主肾阳亏虚、封藏失职；脉软弱至甚为气血阴阳俱虚、正气未复。阳气不能鼓动脉道，故脉软弱无力。"}, {"name": "主虚中夹邪", "desc": "软弱脉可示正虚而邪恋，如疟久左脉软弱、右关弦数，为气血不足而疟邪痰热壅于脾胃；痰积下行后脉转软弱，为邪退正虚；右脉软弱而左脉数有力，为阳明少阳热盛而正气已伤。脉软主虚，兼脉主邪，故属虚中夹实。"}, {"name": "主气虚不摄", "desc": "气虚不能统摄，可见出血、汗泄等症。如右寸极软弱而经行如崩，为气虚血热、血不固；六部软弱无力而痔血，为脾虚不能统血；汗多脉软弱散乱，为气阴将竭、脉不敛。软弱脉示气虚失固，统摄无权。"}, {"name": "主脏腑亏虚", "desc": "软弱脉分见于各部，可定脏腑亏虚。右寸软弱主肺气虚，右关软弱主脾胃虚，两尺软弱主肾阳亏，左脉软弱主肝血不足。如右寸软弱、左弦长，为木行乘金；左细弦右软弱，为肝肾亏而脾胃虚。脉软所在，即脏气不足之处。"}], "n": {"主气血两虚": 27, "主脾虚湿困": 7, "主阳虚阴损": 11, "主虚中夹邪": 14, "主气虚不摄": 3, "主脏腑亏虚": 4}, "a": {"266": "主阳虚阴损", "280": "主阳虚阴损", "2220": "主气血两虚", "2253": "主气血两虚", "3788": "主虚中夹邪", "4712": "主阳虚阴损", "4743": "主阳虚阴损", "4788": "主阳虚阴损", "5810": "主脾虚湿困", "5987": "主气血两虚", "6006": "主虚中夹邪", "6029": "主虚中夹邪", "6043": "主虚中夹邪", "6047": "主气虚不摄", "6048": "主气虚不摄", "6054": "主气血两虚", "6174": "主虚中夹邪", "6215": "主气血两虚", "6248": "主虚中夹邪", "6252": "主脏腑亏虚", "6281": "主气血两虚", "6300": "主气血两虚", "6323": "主虚中夹邪", "6337": "主虚中夹邪", "6341": "主气虚不摄", "6342": "主脾虚湿困", "6348": "主气血两虚", "6469": "主虚中夹邪", "6510": "主气血两虚", "6541": "主虚中夹邪", "6545": "主气血两虚", "6580": "主阳虚阴损", "6966": "主虚中夹邪", "8646": "主阳虚阴损", "8958": "主脾虚湿困", "9226": "主气血两虚", "9430": "主气血两虚", "9858": "主脏腑亏虚", "9953": "主气血两虚", "10661": "主脾虚湿困", "10900": "主气血两虚", "13564": "主气血两虚", "13625": "主气血两虚", "13753": "主阳虚阴损", "14276": "主虚中夹邪", "14652": "主气血两虚", "14733": "主气血两虚", "14899": "主阳虚阴损", "14968": "主脏腑亏虚", "15025": "主气血两虚", "15044": "主气血两虚", "15047": "主阳虚阴损", "15634": "主气血两虚", "15704": "主阳虚阴损", "15737": "主虚中夹邪", "15802": "主脏腑亏虚", "16040": "主气血两虚", "16055": "主气血两虚", "16285": "主气血两虚", "16306": "主气血两虚", "16553": "主气血两虚", "18234": "主气血两虚", "18235": "主脾虚湿困", "18598": "主脾虚湿困", "18608": "主脾虚湿困", "21803": "主虚中夹邪"}, "t": 66, "np": 0}, "c:虚+实": {"o": "虚实脉并非单一脉形，而是以脉之有力无力、按之坚软为纲，统括诸脉所反映的正邪盛衰关系。总起来看，其病机核心在于“邪气盛则实，精气夺则虚”。脉虚者，或为元气自虚、气血衰少，或为阴亏火旺、血虚气弱；脉实者，或为邪热内盛、痰火壅滞，或为宿食瘀血内结。然临床更多见虚实夹杂，如脉虚而证实、脉实而证虚，甚则正虚邪陷、脉无伦次。各类之间以虚实为轴：纯虚纯实各居一端，虚实夹杂为常见之变，而正虚邪陷则为危重之候。故诊脉当首辨虚实真假，再参证候，方能定攻补之宜。", "c": [{"name": "主虚", "desc": "脉来濡弱、微细、虚软无力，按之即无，为元气自虚、气血衰少之象。原文谓“脉来濡者，虚”“脉甚微细，按之即无”“六脉微细之极”，皆精气夺而脉道不充，故主虚证。"}, {"name": "主虚实夹杂", "desc": "脉象虚而证候实，或脉实而证候虚，如“脉虚证实”“脉弦细芤迟”“脉甚虚数”等。原文强调“脉证有不相合者，则必有一真一假”，正虚邪实并见，故脉象虚实互呈，主虚实夹杂之病机。"}, {"name": "主气血虚火旺", "desc": "脉细数无力或弦洪而芤，为阴血亏虚、虚火内动之象。原文谓“六脉细数无力”为气血双亏，“脉弦洪而芤”为热亢阴虚，虚火迫血，故主血虚火旺。"}, {"name": "主正虚邪陷", "desc": "脉微数无伦次、如虾游，或脉微弱沉细无力，为正气内亏、邪气内陷之危候。原文谓“六脉俱微数，极无伦次，又若虾游状”乃胃气衰败、邪陷正脱，故主正虚邪陷。"}], "n": {"主虚": 3, "主虚实夹杂": 26, "主气血虚火旺": 2, "主正虚邪陷": 2}, "a": {"1597": "主虚实夹杂", "2961": "主正虚邪陷", "2997": "主虚", "3384": "主正虚邪陷", "4056": "主虚实夹杂", "12265": "主虚实夹杂", "12266": "主虚实夹杂", "13202": "主虚实夹杂", "14167": "主气血虚火旺", "14393": "主虚实夹杂", "14613": "主虚实夹杂", "15518": "主虚实夹杂", "18360": "主虚", "18714": "主虚实夹杂", "19645": "主虚实夹杂", "19735": "主虚实夹杂", "19753": "主虚实夹杂", "19839": "主虚实夹杂", "20149": "主虚实夹杂", "20185": "主虚实夹杂", "21502": "__np", "21812": "主虚实夹杂", "21825": "__np", "22778": "主虚实夹杂", "22807": "主虚实夹杂", "22869": "主虚实夹杂", "22926": "主虚", "23177": "主虚实夹杂", "23589": "主虚实夹杂", "23797": "主虚实夹杂", "23864": "主虚实夹杂", "24002": "主气血虚火旺", "24515": "主虚实夹杂", "24597": "__np", "26440": "主虚实夹杂", "26577": "__np", "26627": "主虚实夹杂", "26688": "__np"}, "t": 38, "np": 5}, "c:小+濡": {"o": "濡小脉由濡脉与小脉复合而成，总主正气亏虚、湿邪内蕴之病机。其“小”主不足，示气血阴阳亏虚、阳气微弱；“濡”主湿、主虚，示湿邪内停、脉道弛缓。二者相合，常见于气虚阳微、营血亏耗、脾虚湿困、暑湿疟邪、正虚邪恋及虚损劳怯等证。各类之间相互关联：气虚阳微可致湿滞不化，湿邪内蕴又易伤阳耗气；营血亏耗与脾虚湿困常并见，因脾为气血生化之源；暑湿疟邪多因正虚而感，正虚邪恋则是疾病过程中邪正相争的反映；虚损劳怯则为久病深重阶段。总之，濡小脉以虚为本，以湿为标，或虚实夹杂，临证须结合部位、兼脉及症候，辨其主次。", "c": [{"name": "主气虚阳微", "desc": "濡小脉中“小”主正气不足，“濡”主虚，合示阳气微弱。如壮年形伟脉小濡，为阳气式微、浊阴类聚；食少气衰、腹满自痢、脉濡小，为太阴脾阳虚；中年阳微不运，脉形小濡。皆因阳气不振，鼓动无力，故脉道细小而软。"}, {"name": "主湿滞内蕴", "desc": "濡脉主湿，小脉主虚，合见湿邪内蕴而正气已伤。暑湿从口鼻入，湿甚生热，脉濡小；湿热浸淫，湿恋正伤，脉濡小；寒湿内蕴，中虚挟湿，脉形濡小。湿性黏滞，阻遏气机，脉道受困，故见濡小。"}, {"name": "主营血亏耗", "desc": "小脉主不足，濡脉主虚，合示营血亏耗。女子年十六经未行，面色㿠白，心悸，脉濡小无力，为营血亏耗、无以下注冲任；阴虚体质，内热咳嗽，脉息濡小，为阴血不足；尺脉濡小，为肾阴亏虚。血少脉道不充，故脉小；阴亏不能涵阳，脉气软弱，故濡。"}, {"name": "主脾虚湿困", "desc": "右脉濡小，主脾虚湿困。劳倦伤脾，风湿外袭，右脉濡小；不饥，入夜昏谵，脉小右濡，为脾气虚衰、湿浊内困；中虚挟湿，大便溏泄，脉形濡小。脾虚运化失职，湿浊内停，脉道受湿则濡，中气不足则小。"}, {"name": "主暑湿疟邪", "desc": "濡小脉见于暑湿、疟疾。暑湿从口鼻入，湿甚生热，疟发脘痞，脉濡小；疟发先酸疼，后寒热，脉形濡小，为风湿暑邪夹杂、气血同病；脉濡小而驶，脾部兼弦，为暑热伤气、疟邪内郁。暑湿郁遏，气血受伤，故脉濡小。"}, {"name": "主正虚邪恋", "desc": "濡小脉示正气已虚而邪气未净。温病清热后热撤里虚，脉见濡小，下焦空虚；外邪已解，夜热晨退，脉象濡小，为阴分素亏、余热未清；喉腐未痊，忽复热，脉息濡小，为正虚湿恋，无力托邪。正虚不能鼓邪外出，故脉濡小。"}, {"name": "主虚损劳怯", "desc": "濡小脉见于虚损劳怯之候。阴虚体质，内热咳嗽，缠绵年余，肌瘦肉削，脉息濡小，右软，为脾胃日损、气血难复；咳嗽吐血，渐成虚怯，尺脉濡小，为肾阴亏虚、相火上炎。久病耗伤气血阴阳，脉道不充，故见濡小。"}], "n": {"主气虚阳微": 6, "主湿滞内蕴": 2, "主营血亏耗": 5, "主脾虚湿困": 9, "主暑湿疟邪": 6, "主正虚邪恋": 3, "主虚损劳怯": 4}, "a": {"463": "主营血亏耗", "1218": "主气虚阳微", "1293": "主虚损劳怯", "1409": "主暑湿疟邪", "1437": "主脾虚湿困", "1481": "主脾虚湿困", "1506": "主虚损劳怯", "1629": "主气虚阳微", "2345": "主脾虚湿困", "3467": "主暑湿疟邪", "4493": "主营血亏耗", "4529": "主气虚阳微", "4886": "主营血亏耗", "5077": "主气虚阳微", "5809": "主脾虚湿困", "9007": "主暑湿疟邪", "9056": "主湿滞内蕴", "10660": "主脾虚湿困", "11102": "主暑湿疟邪", "13563": "主正虚邪恋", "14651": "主暑湿疟邪", "15095": "主暑湿疟邪", "15157": "主脾虚湿困", "15290": "主气虚阳微", "15488": "主营血亏耗", "15548": "主营血亏耗", "15693": "主虚损劳怯", "15792": "主正虚邪恋", "15830": "主湿滞内蕴", "15942": "主虚损劳怯", "16021": "主脾虚湿困", "16328": "主脾虚湿困", "17367": "主正虚邪恋", "24465": "主脾虚湿困", "24511": "主气虚阳微"}, "t": 35, "np": 0}, "c:浮+虚": {"o": "浮虚脉总以'浮'示病位偏表或虚阳外浮，'虚'示正气不足为核心，总主正虚感邪、气血亏虚、阳虚水湿、虚阳浮越及虚热上浮诸类病机。其浮为风邪在表或虚阳外越之象，虚为营卫气血不足之本质，故常见于表虚感风、劳倦伤中、产后脱血、脾虚木乘等证。各类之间以'正虚'为共同基础：表虚风邪为虚而感邪，气血虚衰为虚而失守，阳虚水湿为虚而水停，虚阳浮越为虚而阳越，虚热上浮为虚而热浮，脾虚木乘为虚而木贼。诸类或相兼为病，如浮虚而涩主风湿阳虚，浮虚而驶主虚热上浮，总不离'虚'字，故浮虚脉为虚证之要脉，凭其兼象可辨虚之所在与兼邪之不同。", "c": [{"name": "主表虚风邪", "desc": "浮虚脉浮为风邪在表，虚为正气不足，主表虚感风。原文如'脉浮虚者，宜发汗'（18940）、'浮则为风，虚则气虚'（10999）、'浮虽风象，而内虚者，脉亦浮而无力'（4490），皆示风邪外袭、卫表不固之机。"}, {"name": "主气血虚衰", "desc": "浮虚脉按之无力，主气血亏虚、中气不固。原文如'脉不常，血气虚也'（3615）、'六脉皆虚浮，按之即无'（19826）为气阴两脱，'脉息虚浮，表气不固'（15995）为气虚表疏，皆示气血虚衰、正气不守之象。"}, {"name": "主阳虚水湿", "desc": "浮虚而涩或浮虚无力，主阳气不足、水湿内停。原文如'脉浮虚而濇者，桂枝附子汤主之'（18910）为风湿相搏、阳虚湿滞；'脉浮虚而濇'（25742）主表虚水饮内停；'浮虚无力'（18280）为里阳不足、阴寒内盛。"}, {"name": "主虚阳浮越", "desc": "浮虚无根之脉，主虚阳外越、元气欲脱。原文如'六脉皆虚浮，按之即无'（19826）为产后过汗、气阴两脱、神魂飞越；'脉浮虚无力'（18280）为'虚阳外越之假象'；'虚火浮越'（3413）亦属此类，皆示虚阳不潜、浮越于外。"}, {"name": "主虚热上浮", "desc": "浮虚而驶或浮数，主虚热上浮、气阴两伤。原文如'脉皆浮虚近驶'（15088）为表虚有热；'肺脉虚浮而快'（3413）为虚火浮越；'汗出脉虚浮'（23169）为热伤气而气少，皆示虚热浮越、正虚邪恋之机。"}, {"name": "主脾虚木乘", "desc": "右脉浮虚而弦，主脾虚肝乘、中气不足。原文如'右脉浮虚颇弦'（15157）为脾肺气虚、土虚木乘；'脾脉偏弦而驶'（15225）为脾虚木乘；'脉浮为虚……弦脉属木见于右手，肝木克脾土'（15248），皆示中虚木乘、气血失和。"}, {"name": "主男女禀赋", "desc": "以脉之沉实浮虚辨男女禀赋，男脉多沉实为坎中满，女脉多浮虚为离中虚，属禀赋体质之辨。"}, {"name": "主阴阳关格", "desc": "人迎寸口脉大数倍，主阴阳偏盛、气血留滞，甚则阴阳离决之危候，属关格病机。"}], "n": {"主表虚风邪": 11, "主气血虚衰": 9, "主阳虚水湿": 5, "主虚阳浮越": 5, "主虚热上浮": 1, "主脾虚木乘": 2, "主男女禀赋": 1, "主阴阳关格": 1}, "a": {"3413": "主虚阳浮越", "3615": "主气血虚衰", "4490": "主气血虚衰", "5011": "主气血虚衰", "8612": "主虚阳浮越", "10999": "主表虚风邪", "15088": "主表虚风邪", "15157": "主脾虚木乘", "15216": "主气血虚衰", "15225": "主虚阳浮越", "15248": "主脾虚木乘", "15480": "主表虚风邪", "15995": "主气血虚衰", "16627": "主气血虚衰", "16738": "主表虚风邪", "18280": "主虚阳浮越", "18910": "主阳虚水湿", "18911": "主阳虚水湿", "18940": "主表虚风邪", "19826": "主虚阳浮越", "20868": "主表虚风邪", "20934": "主表虚风邪", "22918": "主表虚风邪", "22948": "主表虚风邪", "22949": "主表虚风邪", "23053": "主气血虚衰", "23169": "主虚热上浮", "23766": "主男女禀赋", "24057": "主气血虚衰", "24060": "主气血虚衰", "25496": "主表虚风邪", "25742": "主阳虚水湿", "25884": "主阳虚水湿", "25886": "主阳虚水湿", "25973": "主阴阳关格"}, "t": 35, "np": 0}, "c:虚+微": {"o": "虚微脉总属正虚之象，以阳气虚衰、气血大虚为核心，兼及气阴两虚、津液亡失、肾虚不固等虚损病机。其脉虚为不足、微为阳衰，鼓动无力，故主诸虚。然虚微之脉亦可见于正虚邪恋、虚寒夹饮等虚实夹杂之证，如疟久脉虚微中见弦、新产虚微兼沉弦饮邪。各类之间以虚为本，或纯虚，或虚中夹实，总以元气亏虚、阴阳气血不足为共同基础，临床须结合兼脉及症候细辨。", "c": [{"name": "主阳气虚衰", "desc": "虚微脉为阳气大虚之候，如喘不得卧、少阴肾阳式微；脉虚微欲绝为阳气衰微、阴阳离决之兆；脉微为阳虚。阳气虚衰，鼓动无力，故脉虚微，常见畏寒、厥逆、喘促等症。"}, {"name": "主气血大虚", "desc": "虚微脉主气血亏耗，如血崩后气血大亏、气血两亏奇经失养；六脉虚微为元气虚弱、心神虚损；脉微血虚。气血不足，脉道空虚，故见虚微，常伴头眩、心悸、乏力等。"}, {"name": "主气阴两虚", "desc": "虚微脉可见于气阴两伤，如暑月泄泻、六脉虚微为气阴两虚；痉厥后脉象虚微、阴不足而阳有余；轻按虚微为元气虚、重按细数为营阴损。气阴耗损，脉道不充，故虚微。"}, {"name": "主正虚邪恋", "desc": "虚微脉主正气亏虚而邪气未净，如疟久脉极虚微而无力、虚微中见弦，为正虚邪恋；脉虚微热、三阴亏损兼湿热入络；虚微为三阴不足、微热为湿热内蕴。正虚邪滞，脉多虚微兼他象。"}, {"name": "主虚寒夹饮", "desc": "虚微脉主阳虚寒饮内停，如新产六脉虚微、右寸关沉弦，虚寒夹饮；留饮脉微为阳虚；脉微者阳气不足、饮邪内停。阳虚不能化饮，寒饮内伏，故脉虚微，常伴喘满、痰多。"}, {"name": "主肾虚不固", "desc": "虚微脉主下元虚衰、封藏失职，如梦泄脉虚尺微，尺微尤显肾气亏虚、精关不固。肾阳不足，不能固摄，故脉虚微而尺部尤著，常见梦泄、遗精等症。"}, {"name": "主津液亡失", "desc": "虚微脉主津液内亡，如六脉虚微为内亡津液、化源不足；尺脉微者为里虚、禁汗，误汗更伤阴液。津液亏耗，脉道不充，故脉虚微，常伴口渴、小便不利等。"}], "n": {"主阳气虚衰": 6, "主气血大虚": 4, "主气阴两虚": 8, "主正虚邪恋": 3, "主虚寒夹饮": 3, "主肾虚不固": 1, "主津液亡失": 1}, "a": {"1364": "主阳气虚衰", "2992": "主气血大虚", "3439": "主气阴两虚", "7706": "主气阴两虚", "8111": "主虚寒夹饮", "10163": "主肾虚不固", "10883": "主气阴两虚", "10891": "主气血大虚", "13465": "主气阴两虚", "13757": "主正虚邪恋", "13776": "主阳气虚衰", "13816": "主气阴两虚", "13965": "主阳气虚衰", "14870": "主气阴两虚", "14875": "主气血大虚", "14927": "主正虚邪恋", "15614": "主气阴两虚", "18641": "主正虚邪恋", "19361": "主阳气虚衰", "21659": "主虚寒夹饮", "22018": "主虚寒夹饮", "24358": "主阳气虚衰", "25090": "主津液亡失", "25581": "主气阴两虚", "26042": "主气血大虚", "27530": "主阳气虚衰"}, "t": 26, "np": 0}, "c:数+动": {"o": "动数脉总起来主阳动不宁、热扰血脉之病机，其核心在'动'与'数'：数为热，动为阳浮、为痛、为惊。然热有虚实之分，故其主病涵盖虚实两端。实者，热盛火结、风火相煽、火腑壅结，脉多动数有力；虚者，阴虚阳浮、肾精肝血内夺、中虚火浮，脉多动数而尺弱或右脉濡弱。阳动不已则化风为厥，见于厥阴肝病；动数扰及心神则惊怯神乱；热扰冲任则胎动不安。此外，动数脉在病程中可随邪退转为和缓，为向愈之征。诸类之间，以'阳动不宁'为共同基础，虚证实证皆可致阳动，而虚实之辨在于脉之有力无力及兼脉兼症。", "c": [{"name": "主阴虚阳浮", "desc": "脉动数而尺不附骨或寸口独动，为阴精亏虚、阳无所恋而浮越。原文见'真阴未能自旺于本宫'、'肾精肝血内夺，弱阴无能交恋其阳'、'浮阳上越肝膨阴亏'，皆阴不敛阳，故脉动数不静。"}, {"name": "主热盛火结", "desc": "数脉主热，动主阳动不宁。原文见'火腑壅结'、'壮热泄泻'、'风火相煽'、'相火扰动'，皆实热或火邪内结，热扰血脉，故脉动数有力，多见于外感传经、火腑不通等证。"}, {"name": "主阳动风厥", "desc": "动数为阳动不宁，甚则化风。原文见'嗔怒则诸阳皆动，阳动变化内风而为厥'、'肝阳亢动化风'，左脉动如数，症见寒热汗出心悸、神魂散越，属厥阴肝病，阳动风旋之候。"}, {"name": "主虚火中扰", "desc": "数而动主虚火内浮，非实热。原文见'中虚有火，舌光脱液'、'左脉数动，右大略弦'，脾虚不能摄营，虚火内扰，津液受灼；又'脉数减动'因泄后胃乏水谷精气，血脉空虚，亦属虚象。"}, {"name": "主惊怯神乱", "desc": "动主惊、主痛，数主热。原文见'脉来动数，按之则弦'，症见默默不知喜怒、时多疑虑、幻生惊恐、心胆自怯，为心胆气虚、痰热内扰、神魂不安之病机，动数反映神乱不宁。"}, {"name": "主胎动不安", "desc": "尺部动数，数为热扰冲任，动为胎动之象。原文见'脉数尺动，不食恶心，证象恶阻，腰痛见红'，热扰冲任、胎元不固，故既见恶阻又见漏红，主胎漏欲坠，须急安胎。"}, {"name": "主病退向愈", "desc": "动数脉本主热与阳动，若服药后转为迟、浮大减小、初躁后静，则示热减邪衰、正复神安。原文'脉动数，服汤药更迟……此皆愈证也'，说明动数脉在病程中可随邪退而缓和，为向愈之兆。"}], "n": {"主阴虚阳浮": 5, "主热盛火结": 3, "主阳动风厥": 3, "主虚火中扰": 2, "主惊怯神乱": 1, "主胎动不安": 1, "主病退向愈": 4}, "a": {"847": "主阴虚阳浮", "1241": "主热盛火结", "1589": "主阳动风厥", "1780": "主胎动不安", "2939": "主病退向愈", "4454": "主阴虚阳浮", "4504": "主阳动风厥", "5074": "主阴虚阳浮", "5598": "主热盛火结", "6776": "主阴虚阳浮", "6916": "主虚火中扰", "12337": "主阳动风厥", "12875": "主惊怯神乱", "18806": "主病退向愈", "19518": "主阴虚阳浮", "19976": "主病退向愈", "20606": "主虚火中扰", "21820": "主病退向愈", "24357": "主热盛火结"}, "t": 19, "np": 0}, "pc:左+细+软": {"o": "左脉细软总属虚象，细为阴血不足，软为气衰无力，左脉候心肝肾，故其主病以阴血亏虚、气弱阳衰为核心。然细软非独主纯虚，常与他脉兼见而示虚中夹实：兼弦数则虚火痰扰，兼弦浮则脾虚外感，兼洪滑则虚中痰火，兼弦大则血分伏邪，兼浮则虚阳上扰，兼涩则阳虚水停，兼弦硬则胃气衰败。诸类之中，阴虚、气虚为直接主病，虚中夹实、阳虚水停、虚阳上扰、血分伏邪、胃气衰败皆由虚而衍生，或虚而邪凑，或虚而阳浮，或虚而水停，总以正虚为本，邪实为标，故左脉细软一脉，贯穿虚损诸候，而兼脉不同则病机各异。", "c": [{"name": "主阴虚", "desc": "细为阴血不足，软为虚象，左脉候肾，故左脉细软多主少阴肾阴亏虚。原文如'少阴亏而膀胱挟热'、'阴虚于下'、'营阴亏也'，皆以细软示阴液亏耗、脉道不充，常见溺痛、耳蒙、足跟酸痛等症。"}, {"name": "主气虚", "desc": "软为气衰无力，细为血少不充，左脉细软无力主肝肾气虚，右脉细软主脾肺气弱。原文'脾气虚也'、'心肾两虚'、'气虚劳伤之脉'，皆以细软无力示正气亏虚，症见乏力、气短、肢体软弱。"}, {"name": "主虚中夹实", "desc": "左脉细软主本虚，兼见弦数、弦浮、洪滑等脉，示虚中夹痰火、外感或湿热。原文'虚在肝肾，兼以痰火'、'脾虚兼感'、'阳明痰火未清'，皆以细软为虚，他脉为实，症见惊悸、颤振、泻痢、咳喘。"}, {"name": "主阳虚水停", "desc": "左脉细软而左尺带涩，舌白，示阳气式微，阴水内停。原文'通阳泄浊而火象不显，足肿茎囊肿延及少腹'，以细软主阳衰，涩主水湿，症见水肿、气短、小溲不利，属肺降、肾纳、脾运失职。"}, {"name": "主虚阳上扰", "desc": "左脉细软无力主阴虚于下，兼见浮脉则阳冒于上。原文'阴不敛阳，浮阳上越'、'虚阳上扰，下焦不能吸纳'，以细软示下虚，浮示上盛，症见耳蒙鸣响、头眩体麻、口干心烦、遗泄。"}, {"name": "主血分伏邪", "desc": "左脉细软而右脉弦大，或左脉弦大而右脉细软，示营血不足而邪留血分。原文'疟频发，邪留血分也'、'和血以托邪则愈'，以细软主血虚，弦大主邪滞，症见疟疾频发、气血不调。"}, {"name": "主胃气衰败", "desc": "右脉细软而左脉弦硬，示肝木犯胃，胃气已惫。原文'谷不沾唇者已五日，胃气惫矣'，以细软主胃气虚衰，弦硬主肝气横逆，症见呕吐血块痰涎、不纳不便，属气火冲激、湿浊错乱。"}], "n": {"主阴虚": 3, "主气虚": 2, "主虚中夹实": 5, "主阳虚水停": 1, "主虚阳上扰": 3, "主血分伏邪": 1, "主胃气衰败": 1}, "a": {"2297": "主虚中夹实", "7096": "主阴虚", "9094": "主虚中夹实", "9110": "主气虚", "9139": "主虚阳上扰", "9141": "主虚阳上扰", "9851": "主阳虚水停", "10909": "主胃气衰败", "11271": "主虚阳上扰", "11275": "主虚中夹实", "11284": "主血分伏邪", "13745": "主阴虚", "14877": "主阴虚", "15594": "主虚中夹实", "15646": "主虚中夹实", "24758": "主气虚"}, "t": 16, "np": 0}, "pc:左+浮+紧": {"o": "左浮紧脉总以‘表寒’为纲，浮主邪在表，紧主寒邪收引，故其核心病机为外感风寒、寒邪闭结。然因兼脉与分部不同，所主又有层次：单见浮紧多主新感表寒，治宜辛温解表；兼沉弦则寒邪束饮、饮伏于里，主寒饮内伏；见于左脉则寒伤血分，见于右脉则寒伤气分，示寒湿伤分；若暑温见浮紧而形似伤寒，则为火极似水、热极似寒之假象。诸类皆以寒邪为因、表闭为机，或实寒，或寒饮，或假寒，总不离‘浮紧主寒、主表、主闭’之旨。", "c": [{"name": "主外感风寒", "desc": "浮紧为表寒之象，浮主表，紧主寒。原文多段直指‘左脉浮紧为外感风寒’‘寒邪伤营’‘太阳寒邪’，如内伤挟外感、寒邪伤营、太阳寒邪，皆以浮紧定表寒，治用败毒散、麻黄续命汤等辛温解表。"}, {"name": "主寒邪闭结", "desc": "紧脉主寒主痛，浮紧见于左脉，示寒邪闭结经络脏腑。如口噤不语‘左脉浮紧，寒邪闭结’，伏饮‘寒邪束饮’，寒湿痢‘太阳寒湿’，皆因寒性收引凝滞，闭阻气机，故脉浮紧而主寒闭。"}, {"name": "主寒湿伤分", "desc": "左脉候血，右脉候气，浮紧为寒湿外束。原文‘左脉浮紧，血分感寒’‘右脉浮紧，气分感寒’，‘左脉浮紧，寒湿伤血；右脉浮紧，寒湿伤气’，以左右分气血，浮紧定寒湿，示寒湿伤于营血或卫气。"}, {"name": "主寒饮内伏", "desc": "浮紧兼沉弦，示寒邪束饮、饮伏于里。‘左脉浮紧，寒邪束饮’，寸关沉弦为伏饮，沉主伏、弦主饮，浮紧为表寒外束，饮邪内伏，故脉浮紧而主寒饮相搏、阳气阻绝之机。"}], "n": {"主外感风寒": 10, "主寒邪闭结": 1, "主寒湿伤分": 3, "主寒饮内伏": 1}, "a": {"3501": "主外感风寒", "24375": "主外感风寒", "24619": "主外感风寒", "24628": "主寒邪闭结", "24655": "主外感风寒", "24744": "主外感风寒", "24745": "主外感风寒", "24775": "主寒饮内伏", "24795": "主外感风寒", "24796": "主外感风寒", "24820": "主外感风寒", "24948": "主寒湿伤分", "24949": "主寒湿伤分", "25001": "主寒湿伤分", "25040": "主外感风寒"}, "t": 15, "np": 0}, "c:滑+软": {"o": "软滑脉总以痰湿内蕴、正气不足为纲。滑主痰，软主虚（气虚、湿盛或阴伤），故本脉多属虚实夹杂之候。其类可分：痰湿内蕴，症见咳嗽痰多、胸痞呕恶；气虚正伤，症见神疲昏倦、语言错乱；阴液亏虚，症见阴伤浊泛、虚多实少；脾虚湿盛，症见浮肿、二便不畅；正虚疟邪，疟久正虚而痰湿留恋；肝脾不和，气痰交抟而痞胀哕吐。各类之间，以痰湿为标、正虚为本，或偏于气虚，或偏于阴伤，或兼脾运失健，或兼肝木横逆，总不离'虚中夹痰湿'之基本病机。", "c": [{"name": "主痰湿内蕴", "desc": "软滑脉中滑主痰、软主湿，故主痰湿内盛。原文如'脉形软滑'主痰湿阻肺，见咳嗽气逆痰多；'右软滑'主湿痰内蕴，见痞闷不思饮食；'脉软滑'主痰湿内停，见呕吐痰沫。痰湿阻于肺胃、流注经络，皆可见软滑之脉。"}, {"name": "主气虚正伤", "desc": "软脉主正气不足，滑脉主痰，故软滑并见常示气虚痰恋、正虚邪实。原文如'脉滑而软，为气大虚而痰上涌'，见汗出昏倦、语言错乱；'脉象软滑无神'示气阴不足、正气已伤；'软为气虚，滑为痰聚'，见胸痞胀痛。皆以软主气虚、滑主痰实为据。"}, {"name": "主阴液亏虚", "desc": "软滑脉中软可示阴液亏乏，滑示浊痰未净，故主阴伤浊泛。原文如'脉形软滑'，断为'阴分亏损，浊随气火上浮，虚多实少'；又'脉形软滑'属'阴分伤损，浊蒸不化'。软为阴伤、滑为浊恋，故见阴液亏虚而痰浊未楚之候。"}, {"name": "主脾虚湿盛", "desc": "右脉软滑多主脾虚湿盛。原文如'脉右软滑'，释为'软主脾虚，滑主湿盛'，见两足浮肿、朝退夕肿，乃脾虚不能运化水湿；'脉左软右滑'示肝脾气虚、湿滞内蕴，见腹痛二便不畅。软为脾虚、滑为湿盛，故主脾运失健、水湿内停。"}, {"name": "主正虚疟邪", "desc": "软滑脉见于疟疾日久者，主正虚而疟邪留恋。原文如'三疟年余……脉形软滑'，释为'软滑主虚而兼痰湿'，症见寒少热多、肌瘦食减，乃正虚疟邪留恋；又'诊脉软滑，而尺带虚弦'，疟久濒危，示真阴素亏、痰湿内蕴。软滑为虚而兼痰湿之象。"}, {"name": "主肝脾不和", "desc": "软滑脉可主肝木横逆、克脾犯胃，气与痰抟。原文如'脉软滑'，释为'软为气虚，滑为痰聚'，见胸次结痞、胀痛哕吐，乃肝木横逆、克脾犯胃；'脉左软右滑'示肝气不足、脾湿内滞。软滑并见，虚中夹滞，故主肝脾不和、气痰交阻。"}], "n": {"主痰湿内蕴": 3, "主气虚正伤": 2, "主阴液亏虚": 3, "主脾虚湿盛": 2, "主正虚疟邪": 2, "主肝脾不和": 2}, "a": {"135": "主阴液亏虚", "2124": "主气虚正伤", "4664": "主痰湿内蕴", "7262": "主阴液亏虚", "7263": "主阴液亏虚", "7909": "主痰湿内蕴", "8768": "主肝脾不和", "9540": "主痰湿内蕴", "9812": "主肝脾不和", "13191": "主正虚疟邪", "15627": "主脾虚湿盛", "15690": "主正虚疟邪", "16064": "主脾虚湿盛", "17332": "主气虚正伤"}, "t": 14, "np": 0}, "c:大+沉": {"o": "沉大脉总属里实与虚候并见之象。沉主里，大主虚、主热、主郁张，故其病机涵盖虚陷、水停、气郁、湿热、积伏、邪伏、邪滞、热盛等多类。诸类之间，以“沉”定病位在里，以“大”别病性：大而无力多主虚陷、水虚，大而有力多主气郁、积伏、邪伏、邪滞、热盛；兼滞、兼数则偏湿热。虚者阳气不敛，实者邪气壅聚，总由里气不和、升降失司所致。临证须合症辨之，不可一见沉大即断实热，亦不可概作虚寒。", "c": [{"name": "主虚陷", "desc": "沉大脉主中气下陷、虚阳不敛。如尺脉沉大，慎斋断为脾气下陷，脾虚肺失养而自汗，脾阳不舒、肾气郁而足冷；震按亦言沉大非实热，乃虚阳不敛。沉主里，大主虚，故见气陷阳郁之候。"}, {"name": "主水虚", "desc": "沉大脉主水气内停兼正气已虚。李时珍案脉沉而大，沉主水，大主虚，症见胕肿、喘急、便溏、尿少，乃病后冒风，风水相搏。沉为水停于里，大为正虚不敛，故以宣肺利水兼扶正取效。"}, {"name": "主气郁", "desc": "沉大脉主气机郁滞。易思兰案肺脉沉大有力，肝脉弦大时一结，因怒致气郁，气滞血瘀而崩久不止，兼痰喘面青。沉主里，大主郁张，结主气滞，故用香附、乌药等开郁行气而愈。"}, {"name": "主湿热", "desc": "沉大脉主湿阻热蕴、气机不畅。冬温案脉沉大而滞，沉主里，大为阳脉，滞为湿象，数属化热，症见舌灰白滑、便泻、手牵足痛，为湿体蕴热、肺阴受伤、肝风内动。又血淋案脉沉尺大，示下焦湿热未清。"}, {"name": "主积伏", "desc": "沉大脉主积滞内伏下焦。渊按脉浮小沉大，乃积伏下焦，痛则气聚于下，故脉见沉大，非久虚之候。浮小为积未全实于上，沉大示宿积内停、气机壅聚下焦，与腹痛宿积相应。"}, {"name": "主邪伏", "desc": "沉大脉主邪伏于里。疟疾案脉沉而大，寒甚于热，头痛恶寒，为太阳之邪未解，误截则邪不能伏，愈猖獗。沉大示邪结于内，故以石膏、黄芩清阳明，使脾胃和合而愈。"}, {"name": "主邪滞", "desc": "沉大脉主邪滞于里、血气凝涩。风偏枯案诊胃脉沉大，心脉小牢急，沉大示邪滞于里，小牢急示血脉拘急不通，由血气偏虚、风湿客于分腠，血气凝涩不能润养而成偏枯。"}, {"name": "主热盛", "desc": "沉大脉主邪热内传、胃腑热盛。伤寒舌苔由白黄转黑焦干生芒刺，为邪热内传由浅入深；脉沉有力而大渴者主胃腑邪热，脉不实者热未成实。又暑病脉沉而大，沉为湿遏，大为热蒸，阳气为阴邪所遏而见烦躁口渴。"}], "n": {"主虚陷": 3, "主水虚": 1, "主气郁": 1, "主湿热": 3, "主积伏": 2, "主邪伏": 1, "主邪滞": 1, "主热盛": 1}, "a": {"3651": "主虚陷", "3652": "主虚陷", "3748": "主水虚", "4026": "主气郁", "4245": "主虚陷", "7127": "主湿热", "11167": "主湿热", "13672": "主积伏", "14799": "主积伏", "17398": "主邪伏", "22150": "主邪滞", "22937": "主热盛", "27153": "主湿热"}, "t": 13, "np": 0}, "c:滑+紧": {"o": "紧滑脉总以紧主寒（或热结收引）、滑主痰食实邪为纲，所主病机涵盖寒痰壅盛、寒食交阻、胃实脾伤、蛔动吐逆及热结闭癃数类。其核心在于实邪（寒、痰、食、虫、热）与正气相搏，致气机壅滞。诸类之间，寒痰与寒食常相兼为患，皆因寒邪收引、痰食内停；胃实脾伤侧重脾胃本脏实强相攻；蛔动为虫积扰动；热结闭癃则紧从热化，滑直示热实气壅。总不离邪实内结、脉道紧束滑利之象，故治多温通疏运、化痰消食、泻热通闭，随邪之性质而异。", "c": [{"name": "主寒痰壅盛", "desc": "紧主寒，滑主痰，紧滑并见为寒痰交阻之象。原文如3682段'脉紧且滑，痰在上脘'，16141段'沉弦而紧，重按滑而硬'为寒痰胶结，16217段'细紧而滑'为脾胃虚寒痰饮，皆以紧滑示寒痰内盛、壅塞气机。"}, {"name": "主寒食交阻", "desc": "紧主寒邪收引，滑主食积痰滞，右脉或气口紧滑多因感寒停食。15511段'右脉紧滑，感寒夹食'，15514段'气口脉之所以紧滑也'，均言秋令感寒停食而腹痛，寒食交阻中焦，气机不通，故脉紧滑。"}, {"name": "主胃实脾伤", "desc": "趺阳脉候脾胃，滑为胃气实，紧为脾气强或伤。18784段'滑者胃气实，紧者脾气强'，实强相攻致痛；21543段'滑即胃气实，紧即脾气伤'，得食不消、腹满不能食，皆脾胃实强相搏、运化失职之机。"}, {"name": "主蛔动吐逆", "desc": "关上脉紧而滑，为蛔虫扰动之征。21805段明言'关上脉紧而滑者，蛔动'，又滑而大小不均必吐逆，紧滑见于关上，示虫积内扰、胃气上逆，故见吐逆、蛔动之候。"}, {"name": "主热结闭癃", "desc": "紧可主热结收引，滑直主热实气壅。22230段论小便不通由肾与膀胱俱热，'脉紧而滑直者，不得小便也'，紧滑直示热结水道、气机闭涩，故少腹胀急、小便不通。"}], "n": {"主寒痰壅盛": 4, "主寒食交阻": 2, "主胃实脾伤": 2, "主蛔动吐逆": 1, "主热结闭癃": 2}, "a": {"3682": "主寒痰壅盛", "15511": "主寒食交阻", "15514": "主寒食交阻", "16141": "主寒痰壅盛", "16217": "主寒痰壅盛", "18784": "主胃实脾伤", "21543": "主胃实脾伤", "21801": "主寒痰壅盛", "21805": "主蛔动吐逆", "22228": "主热结闭癃", "22230": "主热结闭癃"}, "t": 11, "np": 0}, "e:平": {"o": "平脉总起来主气血调和、阴阳和平，为平人无病或病势向愈之象。其类别关系：首为常脉，应时和缓，示胃气未败；次为病中脉转和平，乃邪退正复之兆，多见于汗后、热退、痢减之际；若和平之中按之无力、缓弱不条，则主正气虚损，或为寒湿内滞、阳气不足；又有脉平而症未除者，或为邪热饮邪深伏、未形于脉，如温疟、支饮之“脉如平”；或为胃气未和、余热未清，如吐利后小烦、舌净脉平而鼻红；更有脉平顺而症反可忧者，如痛减脉平，示邪正混一、攻邪无力。诸类之中，以和平无病与邪退正复为正象，以正虚未复、邪伏脉不显、胃气未和及脉平非吉为变象，临证当脉症合参，不可仅凭脉平断吉凶。", "c": [{"name": "主和平无病", "desc": "脉来从容和缓、三部同等，为气血调和、阴阳和平之象，见于平人无病。如原文“六脉匀平，形色不变，起居如常”示胃气未败；“春肝木王，其脉弦细而长”为应时之平脉，皆属常脉范畴。"}, {"name": "主邪退正复", "desc": "病中脉由数疾、弦滑等转为平和，为邪气渐退、正气来复之佳兆。如“两脉亦渐平”见于热退疹淡，“脉亦渐平”见于邪溃恶候如失，“脉象就平”示郁痰渐化、心肾渐交，皆病势向愈之征。"}, {"name": "主正虚未复", "desc": "脉虽平和而按之无力、缓弱不条，或病后脉平而症未全除，主正气虚损、脾胃未复。如“共见缓弱”主脾虚气弱，“脉虽平而瘕胀痹痛未除”示久病络阻，“脉平而人未全复”示中气受伤，皆虚象未全退。"}, {"name": "主邪伏脉不显", "desc": "脉如平人而症见但热不寒、骨节疼烦、喘不能卧等，为邪热或饮邪深伏，未形于脉。如温疟“脉如平”而但热不寒，支饮“其脉平”而喘不能卧，皆脉症不符，提示辨病当重证候，不可仅凭脉断。"}, {"name": "主胃气未和", "desc": "吐利发汗后脉平而见小烦，为邪去而胃气暂虚、不胜谷气；或脉平而鼻间红色、舌净脉平，为余热未清、阴分受损。如“脉平，小烦者，以新虚不胜谷气故也”，示胃气未复、食入难化。"}, {"name": "主脉平非吉", "desc": "脉平顺而痛反大减，或脉平而瘕胀痹痛未除，非为佳兆，反示邪正混为一家、正气无力抗邪。如喻嘉言治伤寒坏证“脉亦平顺”而痛减，以为可忧，因邪深入腰、血脉久闭，攻邪无力。"}, {"name": "脉论非诊", "desc": "段落为医论评述或注家评议，非实际诊脉记录，无脉象可析，主旨属治学方法或理论探讨。"}], "n": {"主和平无病": 24, "主邪退正复": 39, "主正虚未复": 12, "主邪伏脉不显": 41, "主胃气未和": 7, "主脉平非吉": 12, "脉论非诊": 3}, "a": {"678": "主邪伏脉不显", "695": "主邪伏脉不显", "734": "主脉平非吉", "1279": "主邪伏脉不显", "1404": "主邪伏脉不显", "2000": "主邪退正复", "2015": "主正虚未复", "2096": "主正虚未复", "2097": "主正虚未复", "2157": "主邪退正复", "2314": "主邪退正复", "2315": "主邪退正复", "2923": "主邪退正复", "3066": "主正虚未复", "3071": "主邪退正复", "3078": "主邪退正复", "3360": "脉论非诊", "3458": "主和平无病", "3533": "主正虚未复", "3613": "主邪退正复", "3614": "脉论非诊", "3655": "主邪退正复", "3658": "主邪伏脉不显", "3661": "主邪退正复", "3858": "主脉平非吉", "4165": "脉论非诊", "4184": "主和平无病", "4625": "主邪伏脉不显", "4713": "主正虚未复", "4714": "主和平无病", "5341": "主邪退正复", "5450": "主脉平非吉", "5467": "主胃气未和", "5523": "主正虚未复", "5603": "主邪退正复", "5654": "主邪退正复", "5672": "主邪退正复", "6104": "主邪退正复", "6398": "主邪退正复", "7103": "主邪退正复", "7126": "主胃气未和", "7208": "主邪退正复", "8321": "主邪伏脉不显", "8342": "主脉平非吉", "8725": "主邪退正复", "10397": "主邪伏脉不显", "10400": "主邪伏脉不显", "11094": "主正虚未复", "11299": "主胃气未和", "12858": "主邪退正复", "12872": "主邪退正复", "12933": "主脉平非吉", "12982": "主脉平非吉", "13045": "主邪伏脉不显", "13116": "主邪退正复", "13270": "主邪伏脉不显", "13358": "主邪伏脉不显", "13361": "主邪伏脉不显", "14200": "主邪伏脉不显", "14209": "主邪退正复", "14235": "主脉平非吉", "14497": "主邪伏脉不显", "14506": "主邪退正复", "14534": "主脉平非吉", "14684": "主邪退正复", "14887": "主邪退正复", "15064": "主邪退正复", "15242": "主邪伏脉不显", "15264": "主邪退正复", "15398": "主邪伏脉不显", "15423": "主邪伏脉不显", "15493": "主正虚未复", "15508": "主胃气未和", "15751": "主胃气未和", "15824": "主正虚未复", "16145": "主邪退正复", "16592": "主邪伏脉不显", "16595": "主脉平非吉", "16623": "主邪伏脉不显", "16663": "主邪伏脉不显", "17250": "主邪退正复", "17301": "主胃气未和", "17312": "主邪伏脉不显", "17436": "主和平无病", "17446": "主和平无病", "17459": "主和平无病", "17891": "主邪伏脉不显", "17896": "主邪退正复", "18468": "主邪退正复", "18539": "主邪伏脉不显", "18601": "主邪伏脉不显", "18720": "主和平无病", "18758": "主和平无病", "19016": "主正虚未复", "19043": "主脉平非吉", "19081": "主邪退正复", "19138": "主邪伏脉不显", "19143": "主和平无病", "19487": "主邪伏脉不显", "19666": "主邪退正复", "20058": "主邪伏脉不显", "20178": "主邪伏脉不显", "20327": "主邪退正复", "20439": "主邪退正复", "20991": "主胃气未和", "21053": "主和平无病", "21105": "主和平无病", "21106": "主和平无病", "21107": "主和平无病", "21109": "主和平无病", "21110": "主和平无病", "21210": "主和平无病", "21211": "主和平无病", "21422": "主邪伏脉不显", "21659": "主邪伏脉不显", "21750": "主和平无病", "21790": "主和平无病", "21932": "主正虚未复", "21976": "主邪伏脉不显", "22018": "主邪伏脉不显", "22213": "主邪退正复", "22842": "主和平无病", "22867": "主和平无病", "23001": "主脉平非吉", "23310": "主邪退正复", "23563": "主邪伏脉不显", "23849": "主邪退正复", "24395": "主邪伏脉不显", "24987": "主邪伏脉不显", "25259": "主邪伏脉不显", "25260": "主邪伏脉不显", "25337": "主邪伏脉不显", "25423": "主脉平非吉", "25441": "主和平无病", "25773": "主邪伏脉不显", "25903": "主邪伏脉不显", "26653": "主和平无病", "27902": "主和平无病"}, "t": 138, "np": 0}, "e:促": {"o": "促脉总属阳盛气急、脉行数中一止之象，其病机以阳热亢盛为核心，然有虚实之辨。实者或为温邪内陷、食积化热、瘀血内结、痰气中阻，邪热壅遏、气血不畅而脉促；虚者或为阳虚寒厥、阴精亏虚、中气败散、脏气不续，阳欲伸而力不足，脉亦促。此外，情志激扰、气逆火动亦可致促。诸类之中，阳热亢盛与邪陷阳郁多属实证，治宜清热透邪、通阳宣痹；痰食瘀结宜涌吐、峻下、清消；阳虚寒厥宜灸法通阳；虚损危候则示根本已衰、预后不良，当静养扶正。促脉虽主阳盛，然不可执一而论，须合症辨其虚实，方不致误。", "c": [{"name": "主阳热亢盛", "desc": "促脉数中一止，为阳热亢盛、灼伤阴液，脉行急数而时止。原文谓“阳盛则促”，如温病阳明经证脉洪数而促，壮热大汗、口渴烦躁；食积化热、腑气不通亦见数促，下后脉不促即邪去热退。热盛急迫，故脉促。"}, {"name": "主邪陷阳郁", "desc": "太阳病误下，邪陷胸中，胸阳被遏，脉促胸满，用桂枝去芍药汤通阳；或表未解而里热已迫，脉促利不止，用葛根芩连汤。促为阳气被遏、抗邪外出之象，非纯热盛，故见胸满、下利、喘汗。"}, {"name": "主阳虚寒厥", "desc": "脉促而手足厥逆，为阴寒内盛、阳气被遏，脉气急促不匀，非热盛之促，乃阳欲伸而寒拒之象，可灸以通阳。下痢得促脉，形衰畏冷、小便清长，为脾胃阳微。促在此示阳气虚衰、不相接续。"}, {"name": "主痰食瘀结", "desc": "食积壅塞胸中，新邪与宿食相搏，气机逆乱，寸口脉促；瘀血内蓄，瘀热内结，两关脉促，痛不可近；痰气中结，气口数盛而促。促为邪实壅遏、气血不畅，非虚证，故用涌吐、峻下、清痰。"}, {"name": "主虚损危候", "desc": "久病阴亏火旺，火上刑金，脉促气喘，为真元衰惫、气不接续之危候；痢疾洪数歇止尚可治，若细涩无神而歇止则正虚邪陷，断不可治；色夺脉促，卫阳疏泄。促示根本已虚、脏气不续，预后不良。"}, {"name": "主情志气逆", "desc": "怒伤肝，其脉促而气上冲；悲伤则脉促而人气消。情志激扰，气机逆乱，火激其火，脉变三五不调、或数或止，此促脉非怪脉，调气散服之即安。促主气逆火动、情志所伤。"}], "n": {"主阳热亢盛": 12, "主邪陷阳郁": 15, "主阳虚寒厥": 8, "主痰食瘀结": 8, "主虚损危候": 13, "主情志气逆": 2}, "a": {"3386": "主阳热亢盛", "3452": "主痰食瘀结", "3519": "主阳热亢盛", "3559": "主阳热亢盛", "3661": "主痰食瘀结", "3863": "主痰食瘀结", "4692": "主阳热亢盛", "4941": "主虚损危候", "5060": "主阳虚寒厥", "5227": "主阳热亢盛", "5233": "主阳热亢盛", "5235": "主阳热亢盛", "5841": "主虚损危候", "5867": "主虚损危候", "5869": "主虚损危候", "5871": "主虚损危候", "5872": "主虚损危候", "6721": "主虚损危候", "7090": "主痰食瘀结", "8321": "主阳热亢盛", "10686": "主虚损危候", "10705": "主虚损危候", "10706": "主虚损危候", "10708": "主虚损危候", "13258": "主痰食瘀结", "13575": "主阳虚寒厥", "14105": "主痰食瘀结", "14399": "主痰食瘀结", "15269": "主情志气逆", "16689": "主阳热亢盛", "18730": "主阳热亢盛", "18828": "主邪陷阳郁", "18829": "主邪陷阳郁", "18842": "主邪陷阳郁", "18843": "主邪陷阳郁", "18899": "主邪陷阳郁", "18989": "主阳虚寒厥", "20030": "主邪陷阳郁", "20031": "主邪陷阳郁", "20820": "主邪陷阳郁", "20832": "主邪陷阳郁", "20912": "主阳虚寒厥", "20970": "主邪陷阳郁", "21399": "主邪陷阳郁", "21797": "__np", "21938": "主邪陷阳郁", "22760": "主阳热亢盛", "22819": "主情志气逆", "22875": "主阳虚寒厥", "22880": "主虚损危候", "22976": "主阳虚寒厥", "22989": "主阳虚寒厥", "24413": "主阳热亢盛", "24467": "主邪陷阳郁", "25736": "主虚损危候", "25810": "主邪陷阳郁", "25830": "主痰食瘀结", "25884": "主阳虚寒厥", "26084": "主邪陷阳郁"}, "t": 59, "np": 1}, "c:大+小+迟+长+短": {"o": "迟大小长短脉所主病机，总以脉与形性相应为吉、不相应为凶为纲。具体可分四类：形性相应为常度；伤寒热盛脉浮大主邪实外达；汗后脉沉小主正伤而宜静敛；温病脉细小难得主正虚邪陷。四类之间，以‘相应’为吉凶判断核心：脉与体质、病期相符则生，反之则死。迟大小长短之象，须结合形性、病证与汗下情况综合审视，方能准确判断正邪胜负与病势顺逆。", "c": [{"name": "主形性相应", "desc": "脉之迟速大小长短与人之大小短长、性气缓急相符则为吉，反之则凶。原文强调‘皆如其人形性者吉’，说明脉象与体质形性相应是常度，不相应则提示病机逆常。"}], "n": {"主形性相应": 1}, "a": {"21824": "主形性相应"}, "t": 1, "np": 0}, "c:数+弦+细+虚": {"o": "弦细虚数脉总属阴虚阳浮、气血两虚之候，以阴血亏虚为本，虚阳浮动为标。弦为肝郁阳亢，细为阴血不足，虚为气耗，数为虚热。五段所主，或肝肾阴虚、虚阳上冒，或气血两虚、虚热内生，或肝阳上越、风阳浮动，或阴虚灼液、痰热搏结，或内损虚火伏藏。诸类皆以阴亏为基础，阳浮为共性，虚实夹杂。其病位多在肝肾，涉及脾肺；病性属虚多实少，虚火、痰热为标。脉症合参，当以滋填潜镇为治，忌泄气伤阴。", "c": [{"name": "主阴虚阳浮", "desc": "弦细为肝肾阴血不足、阳不潜藏，虚数为虚阳浮越。如319段左弦细右虚数，断为虚阳上冒、肝肾根蒂不固；14539段弦细虚数，为营阴素亏、风阳浮动，痉厥之萌。阴亏于下，阳浮于上，故脉细虚而数。"}, {"name": "主肝阳上越", "desc": "弦为肝脉，数为阳热，细为阴伤。10546段弦数主肝阳上越，头晕偏痛；14263段左关弦、尺细而干，为水不涵木、风阳内炽。肝阴不足，阳失所制，化风上扰，故脉弦细而数。"}, {"name": "主痰热搏结", "desc": "弦主肝阳，细干主阴亏，数主热，痰由热灼津液而成。14263段寸滑如珠、尺细而干，断为风阳内炽、搏液成痰。阴虚阳亢，灼液为痰，痰热内蕴，故脉弦细数中兼滑。"}, {"name": "主内损虚火", "desc": "弦细数为阴虚内热之象。13968段腰疽愈而复发五年，脉弦细以数，孟英断为内损证，非外疡实邪，用甘润滋填而痊。阴亏于内，虚火伏藏，脉细数而弦，为内伤虚损之征。"}], "n": {"主阴虚阳浮": 2, "主肝阳上越": 1, "主痰热搏结": 1, "主内损虚火": 1}, "a": {"319": "主阴虚阳浮", "10546": "主肝阳上越", "13968": "主内损虚火", "14263": "主痰热搏结", "14539": "主阴虚阳浮"}, "t": 5, "np": 0}, "c:数+弦+滑+软": {"o": "弦数软滑脉总属痰湿内蕴、郁热化火、阴液亏虚、风阳内动之候。其核心病机为痰湿化热，本虚标实，涉及肺、肝、胃等多脏。弦主饮癖，数主热，软为虚（阴亏），滑主痰，四者相合，揭示痰湿壅塞、气机郁滞、久郁化热、热盛风动、阴液受灼之病机。各段原文均见痰湿、热盛、阴亏、风动相互交织，如'积痰作迷'示痰湿蒙窍，'苔黑肢瘛'示热盛风动阴亏。四类病机中，痰湿为发病之基，热盛为痰湿郁化之果，阴亏为热盛灼伤之因，风动为热盛阴亏之极，彼此关联，共同构成痰热阴亏风动之复杂证候。", "c": [{"name": "主痰湿", "desc": "脉软弦滑数，软为虚，弦主饮，滑主痰，数主热。原文'积痰作迷，迷则神蒙'乃痰湿蒙蔽清窍，兼小溲色深为湿热下注。脉象示痰湿化热、本虚标实之机，故宜先治痰湿，痰去则神自清。"}, {"name": "主热盛", "desc": "脉弦数软滑，弦数主肝热风动，软滑为痰热内蕴。秋感服温散而日重，苔黑肢瘛，乃温散助热，引动肝风，痰热蒙扰，有厥逆之势。故急予清凉涤痰、息风开窍，服后脉较和，示热势渐退。"}, {"name": "主阴亏", "desc": "脉见弦数软滑，弦为风阳，数为热，软为阴亏，滑主痰。秋感服温散药而日重，苔黑肢瘈，乃温燥助热，阴液受灼，风阳挟痰上扰。脉象示阴亏热炽、痰风内动之机，故急予清凉息风、化痰养阴。"}, {"name": "主风动", "desc": "脉弦数软滑，弦数为热盛风动，软为阴亏，滑为痰。秋感服温散药而日重，苔黑肢瘛，是温散助热、阴液受灼、痰热内扰、风阳欲动之候。脉较和则示药后热势渐退、阴液渐复，故一路清凉渐以向愈。"}], "n": {"主痰湿": 1, "主热盛": 1, "主阴亏": 1, "主风动": 1}, "a": {"9643": "主痰湿", "13011": "主风动", "14117": "主阴亏", "14412": "主热盛"}, "t": 4, "np": 0}, "c:数+滑+微+软": {"o": "软滑微数脉总起来主阴亏、痰饮、内热三者交织为病。软脉主阴液亏虚，滑脉主痰饮内盛，微数脉主阴虚内热，三者相合，正合“阴亏痰热”之病机。原文三段落均见于产后发热案，患者素体阴亏，新产血去则阴愈亏，阴虚生内热故脉数而微；痰饮内盛故脉滑；阴亏脉道不充故脉软。痰热内蕴则谵妄昏瞀，渴喜热饮似寒实热。三类病机相互关联：阴亏为病之本，痰饮为病之标，内热为阴亏痰郁所化，共同构成虚中夹实、本虚标实之候。故治疗当养阴清热、化痰蠲饮，不可误作风寒表散或瘀血攻通。", "c": [{"name": "主阴亏", "desc": "脉软为阴亏之象，原文谓“素体阴亏”“新产血去”，阴液亏虚则脉道不充，故脉软；阴亏生内热，故脉微数。三段落均以软脉主阴亏，为病本之一。"}], "n": {"主阴亏": 3}, "a": {"13468": "主阴亏", "14010": "主阴亏", "14306": "主阴亏"}, "t": 3, "np": 0}, "c:数+弦+浮+空": {"o": "空数浮弦脉在此案中总属暑湿伤气、阴液耗伤而暑热未清之候。初起脉微弱为暑湿本象，示气机受困；病延日久，脉转数而未空，反映暑热未清、阴液已伤，然胃气未绝。四类病机相互关联：暑湿伤气为始因，暑热未清为病进，阴液耗伤为结果，而胃气未绝为转机之关键。脉象由弱转数，提示邪未去而正渐伤；未至空豁，说明胃气尚存，故可清热养阴并进。总以暑湿化热、伤气耗阴、胃气未绝为辨治要点。", "c": [{"name": "主暑湿伤气", "desc": "原文谓“初起脉微弱，为暑之本象”，弱微之脉反映暑湿之邪耗伤正气，气机困阻。症见滞下、谷食不思、气短汗多等，皆暑湿伤气、脾胃受困之候，故脉弱体虚为暑湿本象。"}], "n": {"主暑湿伤气": 2}, "a": {"13212": "主暑湿伤气", "13916": "主暑湿伤气"}, "t": 2, "np": 0}, "c:数+细+沉+紧": {"o": "沉细紧数脉总起来主阴毒内结、寒盛阳衰之候。其沉细主里虚寒、阳气衰微；紧主寒凝气滞、疼痛；数在此非热，乃寒邪逼迫、阳气挣扎之象。三者相合，反映阴寒内盛、毒气攻心、阳气不达的病机。原文所载‘身重背强，腹中绞痛，咽喉不利，毒气攻心，心下坚强，短气不得息，呕逆，唇青面黑，四肢厥冷’等症，皆阴毒内结、寒凝血脉、阳气衰微之表现。各类病机之间相互关联：阴寒内盛为根本，导致寒凝气滞而见紧脉，阳气衰微而见沉细，毒气攻冲而见数脉，共同构成阴毒之候的脉象特征。", "c": [{"name": "主阴寒内盛", "desc": "脉沉细紧数，沉细为阴寒内盛、阳气衰微之象。原文见‘腹中绞痛，咽喉不利，毒气攻心，心下坚强，短气……四肢厥冷’，皆阴毒内结、寒凝血脉、阳气不达之候，故脉沉细紧数正合阴毒寒盛阳衰之机。"}], "n": {"主阴寒内盛": 2}, "a": {"21386": "主阴寒内盛", "21909": "主阴寒内盛"}, "t": 2, "np": 0}, "pc:右+数+弦+细+虚": {"o": "右·数弦细虚脉总属阴阳两损、虚阳上冒之候。其脉象由左弦细与右虚数复合而成：左弦细主肝肾阴虚、阳不潜藏；右虚数主脾肺气虚而虚阳浮越。二者相合，反映下焦阴亏不能上承，冲脉震动，诸脉俱逆，虚阳上冒，故见眩晕、盗汗、咳嗽气短、行走喘促等症。四类病机中，'主肝肾阴虚'与'主脾肺气虚'分述左右脉象所主，'主虚阳上冒'为共同病机转归，'主阴阳两损'则统括整体体质。诸类相互关联，总以虚为本，阳浮为标，非肝经自病，亦非实邪为患，故前医误用泄气伤阴之品反致害之。", "c": [{"name": "主虚阳上冒", "desc": "脉右虚数，虚为气阴不足，数为阳浮于上。原文谓'虚阳上冒'，因下焦阴不上承，冲脉震动，诸脉俱逆，故见眩晕、盗汗、咳嗽气短、行走喘促，皆虚阳上浮之象。"}], "n": {"主虚阳上冒": 1}, "a": {"319": "主虚阳上冒"}, "t": 1, "np": 0}, "pc:六+沉+涩+伏+结": {"o": "六·沉涩伏结脉总属虚实夹杂之候。沉伏为气血内滞、阳气不达，结涩为血虚津枯、脉道不利。三者相合，既主血虚津枯，又主气血内滞，并可兼见胃气虚。原文一案年五十余、体瘦、便燥、食少、腹痛，虞氏初作血虚治，以四物汤加润下之品；因胃气虚不能受速药，改以蜡匮备急丸缓达下焦。可见此脉所主以血虚津枯为本，气血内滞为标，胃气虚为兼，三者相互影响，构成虚中夹滞之病机格局。", "c": [{"name": "主血虚津枯", "desc": "沉涩结脉主血虚津枯。原文'六脉皆沉伏而结涩'，结涩为血虚津枯、脉道不利；患者年五十余、体瘦、便燥、食少，皆阴血不足之象，故虞氏作血虚治，用四物汤加减。"}], "n": {"主血虚津枯": 1}, "a": {"3805": "主血虚津枯"}, "t": 1, "np": 0}, "c:弦+细+沉+濡": {"o": "弦细沉濡脉总属湿邪为患，主湿郁、湿蕴阳郁及湿浊弥漫。弦细主湿郁，强调湿邪阻滞气机，脉道拘急而细；沉濡主湿邪内蕴、阳气不宣，突出湿浊在里，阳气被遏；脉象模糊则示湿浊弥漫三焦，脉道不清。三者相互关联，共同反映湿温病中湿浊偏盛、三焦气机壅滞、阳气不宣之病机。原文以通三焦、渗湿之苦辛淡法治疗，久服方解，印证了湿邪黏滞、病程缠绵的特点。", "c": [{"name": "主湿郁", "desc": "脉弦细主湿邪郁滞。原文‘弦细主湿郁’，湿性黏滞，阻遏气机，脉道拘急则弦，湿邪困阻则细，故弦细并见提示湿郁为患。"}], "n": {"主湿郁": 1}, "a": {"5246": "主湿郁"}, "t": 1, "np": 0}, "c:数+弦+滑+紧": {"o": "滑数弦紧脉总主温疫毒邪化火，充斥内外，蔓延三焦。右脉滑数主火盛痰热，左脉弦紧主邪郁少阳。二者相合，反映疫毒炽盛，邪势鸱张，火邪充斥表里三焦，故见发热咽痛、丹痧连片、颈肿舌红等症。其病机核心为火毒壅盛，兼少阳郁滞，属邪实正盛阶段，需防热毒内陷致神昏发痉。", "c": [{"name": "主火盛", "desc": "右脉滑数，滑主痰湿，数主热，滑数相合主痰火热盛。原文温疫之邪化火，充斥内外，发热咽痛、遍身丹赤、痧点连片，舌红赤点，皆火盛之象，故滑数主火邪炽盛。"}], "n": {"主火盛": 1}, "a": {"7428": "主火盛"}, "t": 1, "np": 0}, "pc:右+数+弦+滑+紧": {"o": "右·数弦滑紧脉总属温疫疠邪从内而发、化火充斥之候。其脉象复合，滑数主温疫化火、热壅三焦；弦紧主邪郁少阳、势张未透。二者相合，既示火邪炽盛蔓延内外，又示邪郁少阳不得外达，郁火相搏，有内窜心包、致神昏发痉之虞。三类病机以‘温疫化火’为根，‘邪郁少阳’为枢，‘火窜心包’为变，层层递进，总归于温疫火毒充斥三焦、郁而内陷之机。", "c": [{"name": "主温疫化火", "desc": "右脉滑数，为温疫之邪从内发而化火之象。原文谓‘温疫之邪，一发而便化为火，充斥内外蔓延三焦’，滑主痰热内壅，数主火邪炽盛，故脉滑数主温疫化火、热势充斥内外。"}], "n": {"主温疫化火": 1}, "a": {"7428": "主温疫化火"}, "t": 1, "np": 0}, "c:数+弦+虚+实": {"o": "数弦实虚脉总起来主邪实内盛、气滞热结，兼有正虚之象。数主热、主邪盛，弦主痛、主气滞，二者相合，反映热邪与气滞互结，营气阻滞，气聚成形，故见腹中痛胀、寒热往来等实象。然原文谓“恐从实变虚”，提示邪实日久耗伤正气，病机由实转虚，实中夹虚，预后堪虑。各类病机中，热与气滞为病之因，痛为病之果，实中夹虚为病之转归，彼此关联，共同构成产后营滞气聚、邪实正伤之候。", "c": [{"name": "主热", "desc": "数脉主热，原文脉数而弦，数主热、主邪盛，说明热邪内盛，正邪交争，故见数象。"}], "n": {"主热": 1}, "a": {"8110": "主热"}, "t": 1, "np": 0}, "c:数+浮+小+濡": {"o": "浮小濡数脉总属虚多实少之候，核心病机为气阴两伤、虚热内扰，兼脾肺气虚与暑湿未清。浮为气虚外浮或邪恋表分，小濡为阴血不足、脉道不充，数为虚热鼓动。右脉尤不足，突出脾肺气虚；病疟日久、截药伤正，使气阴耗伤，暑湿余邪未净。四类病机相互关联：气阴两伤为根本，脾肺气虚加重脉之弱象，暑湿未清致濡浮不除，虚热内扰使数象显现。总以正虚为主，虚中夹实，治当益气养阴、清暑化湿，忌纯用截疟攻伐。", "c": [{"name": "主气阴两伤", "desc": "脉浮小而濡带数，浮为气虚外浮，小濡为阴血不足、脉道不充，数为虚热内扰。原文谓“气阴两伤、虚热内扰”，且病疟日久、截药伤正，气阴耗伤，故脉象虚浮而数。"}], "n": {"主气阴两伤": 1}, "a": {"15079": "主气阴两伤"}, "t": 1, "np": 0}, "pc:左+数+弦+大+浮": {"o": "左·数弦大浮脉总属肝气亢逆、气火郁勃之象，以弦为肝郁，数为热急，浮大为气火升浮，四者相合，主气火内郁、木旺克土。其病机核心在肝脾失调：肝气郁而化火，火性急迫则脉数大；木旺乘土，脾运受戕则食少肌削；然病久正伤，阳气衰微，寒来脉转沉微，故又见虚实错杂。三类病机相互关联：气火郁勃为始动，木旺克土为传变，虚实错杂为转归，总以肝郁化火、脾土受困、正虚邪实为脉络。", "c": [{"name": "主气火郁勃", "desc": "脉浮大弦数，浮主气浮，大主火盛，弦主郁滞，数主热急。原文谓‘浮大弦数为气火郁勃’，因性躁多能、肝气亢逆，气郁化火，火性急迫，故脉来浮大弦数，按之不减，为实火郁勃之象。"}], "n": {"主气火郁勃": 1}, "a": {"15247": "主气火郁勃"}, "t": 1, "np": 0}, "pc:左+虚+涩+小+濡": {"o": "左脉虚涩小濡，总属气血两虚、脾虚湿困之候。虚小主气血不足，涩主血少行滞，濡主脾虚湿困。三者相互关联：气血亏虚则脉道不充而见虚小，血少行滞则脉涩，脾虚湿困则脉濡。原文经行前后多少不定、腰胯酸疼、缠绵不已，皆气血两虚、冲任失养所致；服养阴止经剂即停，亦示阴血亏虚。法宜气血并调，切中虚涩濡小之脉。故本脉所主以虚为本，兼有血滞与湿困，然皆由气血不足、脾虚失运衍生，总不离虚损之机。", "c": [{"name": "主气血两虚", "desc": "脉虚小为气血不足之象，原文'虚小为气血不足'直接点明。经行前后多少不定、缠绵不已，皆气血两虚、冲任失养之候，故脉见虚涩濡小。"}], "n": {"主气血两虚": 1}, "a": {"15962": "主气血两虚"}, "t": 1, "np": 0}, "c:细+滑+沉+疾": {"o": "沉细滑疾脉总属里热炽盛、阴分受灼之候。沉细为阴脉，主病位在里、阴血不足；滑疾为阳脉，主痰火内盛、气机壅滞。四者合见，阴中伏阳，热郁于里而阴液已伤，故以“热”为核心病机。原文“脉沉细滑疾者热”一句直指其要，并与“脉数在腑”“脉滑多血少气”等条互参，可见其热多兼痰食积滞、气血失调。三类病机中，主热为总纲，气血失调为兼夹，脏腑积热为病位所在，三者相互关联，共同构成沉细滑疾脉的复合病机。", "c": [{"name": "主热", "desc": "原文明言“脉沉细滑疾者热”。沉细为阴脉，滑疾为阳脉，阴中伏阳，热郁于里。滑主痰食，疾主火盛，细为阴伤，合见则里热炽盛而阴分受灼，故主热证。"}], "n": {"主热": 1}, "a": {"21801": "主热"}, "t": 1, "np": 0}, "pc:左+数+弦+洪": {"o": "左数弦洪脉总属肝木化火、热盛阴伤之候。弦为肝脉，洪数为火热，故其核心病机为肝火亢盛；火盛则灼阴，故兼阴伤；木火刑金，灼津为痰，则痰热内蕴；火盛阳升，肝阳上僭，则见气冲、面赤、不眠；若邪热内陷，郁结不达，则脉见洪数中带紧涩。诸类以肝火亢盛为始，火盛灼阴则阴伤，阴不制阳则阳僭，火炼津液则痰生，邪郁不达则内陷，相互交织，总以木火亢盛、阴伤痰热为要。", "c": [{"name": "主热盛阴伤", "desc": "洪数主热盛，热盛则灼伤阴液，故脉数而洪，兼见阴亏之候。原文言‘细数如丝则阴分已亏’，谓‘左弦洪而数为阴虚挟热’，皆示热炽与阴伤并存。"}, {"name": "主痰热内蕴", "desc": "右脉滑数而溢，滑主痰，数主热，溢为热壅气逆，故主痰热内蕴。原文称‘右脉滑数而溢……为痰热内蕴’，亦谓‘右滑而溢为痰挟风阳’，皆以滑数溢并见为痰热之据。"}, {"name": "主肝阳上僭", "desc": "弦洪数而见气冲、面赤、不眠等症，为肝阳升逆无制。原文谓‘弦洪为肝阳亢盛’，言‘肝阳上浮’，见‘气冲咳嗽，血涌如泉’，皆因木火化风，阳升气逆所致。"}, {"name": "主邪热内陷", "desc": "洪数之中兼结滞紧涩，为邪热内陷、郁结不达之象。原文谓‘洪为邪热盛，弦主邪郁，数主热，紧涩结滞乃……表邪内陷，热郁不得外达’，故脉虽洪数而中带紧涩，主邪热内陷。"}], "n": {"主热盛阴伤": 1, "主痰热内蕴": 1, "主肝阳上僭": 2, "主邪热内陷": 1}, "a": {"4233": "主热盛阴伤", "13279": "主肝阳上僭", "13937": "主肝阳上僭", "14197": "主痰热内蕴", "18256": "主邪热内陷"}, "t": 5, "np": 0}, "c:弦+微+软": {"o": "软微弦脉总属虚实夹杂之象，以虚为本，以郁为标。软脉主正气不足、气虚湿困，微弦主气机郁滞、肝木偏亢。归纳其病机主要有四类：一为气虚湿困，湿郁痰滞，见腹中不舒、便溏头蒙；二为脾虚木乘，土虚肝亢，见足肿神疲、胃呆畏寒；三为气郁痰滞，痰气窒塞，发为流痰、络脉失养；四为气营交困，气血两伤，形消色瘁、经事渐稀。四类之间相互关联：气虚湿困为病之始，湿郁化痰、气机壅滞则成痰滞；脾虚不运，肝木乘之，则土虚木侮；久病耗伤，气不生血，则气营交困。总以正气亏虚为本，湿、痰、气郁为标，虚实兼夹，病程缠绵，故原文多谓'病道深远，不易旦夕奏功'。", "c": [{"name": "主脾虚木乘", "desc": "软主脾虚气弱，微弦为肝木偏亢，土虚则木乘。原文'右微弦则土虚木乘'，见脱力、足肿、胃呆、畏寒；'中虚木侮，生化无权'，症见便泻肠鸣、形消色瘁、经事渐稀。皆因脾气虚弱，肝木克伐，运化失职，故脉软而微弦。"}, {"name": "主气郁痰滞", "desc": "微弦主气机郁滞，软主气虚不运，气郁则津液不布，聚湿生痰。原文'气不化湿，湿郁蒸痰，痰气窒滞'，见腹中不舒、大便不流利、头蒙；'气郁化痰，痰入筋骨间，发为流痰'，溃后气营交困，络脉失养。故软微弦脉主气郁痰滞、痰气窒塞之病机。"}, {"name": "主气营交困", "desc": "软为气分不足，微弦为肝郁血少，气血两伤则气营交困。原文流痰溃后'气营交困，络脉失养'，患处肿木、手臂不能举动；'气久虚而血将涸'，形消色瘁、经事渐稀。皆因久病耗伤，气不生血，营血亏虚，脉络失养，故脉见软而微弦。"}], "n": {"主脾虚木乘": 3, "主气郁痰滞": 1, "主气营交困": 1}, "a": {"9639": "主气郁痰滞", "9727": "主脾虚木乘", "9833": "主脾虚木乘", "10036": "主气营交困", "13130": "主脾虚木乘"}, "t": 5, "np": 0}, "c:数+滑+虚": {"o": "虚滑数脉总起来主正虚邪恋、虚中夹实之证。其‘虚’为气阴两伤、肝肾式微或脾虚失运；‘滑数’为湿热痰浊或痰火内蕴。二者相合，形成正虚与邪实并存之局：或湿热伏邪留恋阳明而气阴已伤（），或久病羸弱、阴不交阳而痰火内迷（），或郁怒伤肝、木旺土衰而痰热内蕴（滑数虚软脉总述），或心肾阴亏、痰火交结而水火不济（）。各类病机相互关联：正虚为发病基础，痰热湿浊为病理产物，痰火又可乘虚上蒙清窍、扰动心神，或横逆犯脾、下耗肝肾，形成虚→痰→火→更虚的恶性循环。故其主病虽以湿热痰浊为标，而气阴亏虚、脏腑失调为本，总属本虚标实、寒热错杂之候。", "c": [{"name": "主气阴两伤", "desc": "虚滑数脉中‘虚’为气阴不足之象。原文言‘虚为气阴已伤’，言‘虚为久病羸弱、肝肾式微’，言‘左寸虚数卜心神失守，左尺虚浮知肾水有亏’。虚象贯穿三候，提示正气亏耗，尤以气阴、肝肾之阴为著。"}, {"name": "主痰火蒙窍", "desc": "滑数之痰火与虚象相合，易上蒙清窍、扰乱神明。原文言湿热‘上蒙清窍，神明无以自主’，致谵语郑声；言‘痰火内迷，乘虚厥动，精识蔽蒙，语言失绪’；亦见痰火交结而心神失守。此乃虚中夹实、痰火乘虚上扰之机。"}, {"name": "主心肾不交", "desc": "原文以左寸虚数、左尺虚浮分候心肾，言‘心神之失守’‘肾水之有亏’，火升则心惕足冷，火降则惕止足暖，总由脾不媒合心肾，水火难济。虚数示阴亏火动，滑为痰火内蕴，故心肾不交兼痰火交结。"}], "n": {"主气阴两伤": 1, "主痰火蒙窍": 1, "主心肾不交": 1}, "a": {"116": "主气阴两伤", "15705": "主心肾不交", "18512": "主痰火蒙窍"}, "t": 3, "np": 0}, "c:细+浮+紧": {"o": "浮紧细脉总起来主外感风寒、表邪郁闭，兼见正气不足或里虚寒盛之病机。浮主表，紧主寒，细主正虚或寒邪收束，三象合参，提示寒邪束表而营卫郁滞，且常兼气血不足或阳气不振。其具体所主，一为太阳正伤寒，寒邪闭表，无汗烦躁；二为产后正虚感寒，表里皆邪，里冷益深；三为疮疡兼表邪，风寒束表而阳气不振。三类均以浮紧细为共同脉象，但兼症不同，或纯实，或虚实夹杂，或疮疡兼表，总不离外寒束表、营卫不和之基本病机，而细脉又提示正气不足或寒邪收束之机。", "c": [{"name": "主表寒", "desc": "浮主表，紧主寒，细为寒邪束表、营卫郁滞。原文见发热恶寒、头项强痛、无汗胸痞，脉浮紧细，属正伤寒太阳表症，寒邪闭表，阳气不得宣发，故无汗而烦躁，当发汗解表。"}, {"name": "主正虚感寒", "desc": "浮主表邪，细主正虚，紧主寒。原文见产后气血大伤，经水大行之后，外感风寒，咳嗽恶寒，呕吐痰水，前医误补致表邪不解，里冷益深，脉浮细而紧，为风寒积冷、表里皆邪、正虚邪恋之象。"}, {"name": "主疮疡表邪", "desc": "脉浮紧细见于疮疡患者，浮紧细为风寒束表、营卫不和，兼脉缓涩体倦恶寒则示气血不足、阳气不振。原文以散风助阳法治之，说明疮疡兼表邪与正虚，浮紧细主外感风寒之表邪未解。"}], "n": {"主表寒": 1, "主正虚感寒": 1, "主疮疡表邪": 1}, "a": {"10914": "主表寒", "16214": "主正虚感寒", "24291": "主疮疡表邪"}, "t": 3, "np": 0}, "c:数+滑+空": {"o": "滑数空脉总起来主痰火内盛与阴精亏耗并见的复杂病机，其核心为火盛水亏、本虚标实。滑数主痰火，空主阴亏，二者复合反映邪热鸱张而根本已伤。所主病机可归为四类：主痰火、主阴亏、主火盛水亏、主正虚邪盛。其中痰火与阴亏是基础病理要素，火盛水亏是二者相互作用的病机概括，正虚邪盛则是对危重格局的总体描述。各类之间相互关联：痰火为标，阴亏为本，火盛水亏为标本同病之机，正虚邪盛为病势深重之候。临床可见于声哑语难、经事不调、似胎非胎等症，均以滑数而空为辨治眼目。", "c": [{"name": "主阴亏", "desc": "空脉主阴精亏耗、脉道不实。原文反复强调“空则阴精亏耗”“空则阴精已亏”，如案21、案43均以空为水亏本伤之征，案34亦因空而断非胎非瘀，故本脉主阴亏血少、根本先损之病机。"}, {"name": "主火盛水亏", "desc": "滑数主火盛，空主水亏，二者并见反映火旺水亏、本伤机失之复杂病机。原文如案21“火旺水亏伤”、案43“火炎于上、根本先损”，均以滑数而空概括火盛于上而阴亏于下的病理格局。"}], "n": {"主阴亏": 1, "主火盛水亏": 2}, "a": {"12609": "主火盛水亏", "12628": "主阴亏", "12843": "主火盛水亏"}, "t": 3, "np": 0}, "c:细+微+伏": {"o": "微细伏脉总起来主邪闭气机与气血不足，并可见于暴病暴逆及久病将绝之候。其核心在“伏”：伏为脉道一时隐蔽不见，多因邪气内闭、气逆不通，或气脱不续，属暴病暴逆者，调气可复；而微细则示气血不足，若与伏并见，则邪闭之中已寓正虚。若积困延绵，脉由微细渐至隐伏，则非真伏，乃残烬将绝之兆。故本脉所主，实分两类：一为暴病邪闭、气机不通，脉伏而微细，治当宣通；二为久病正衰、气血耗竭，脉微细渐伏，属危候。二者虽同见微细伏，然新久虚实迥异，须结合证候辨别。", "c": [{"name": "主邪闭气机", "desc": "脉微细而伏，伏为邪气内闭、气机不通。原文见暑热秽毒内闭心包，阳气不达而脉伏；又痧毒深伏，气血内闭，脉亦微细而伏。故伏脉主邪闭，非虚脱可比。"}, {"name": "主暴病暴逆", "desc": "原文论伏脉见于胸腹痛剧、气逆于经、脉道不通，或偶因气脱不相接续，必暴病暴逆乃有之，调其气而脉自复。故微细伏脉可主暴病暴逆、气机一时闭塞。"}], "n": {"主邪闭气机": 2, "主暴病暴逆": 1}, "a": {"18450": "主邪闭气机", "18470": "主邪闭气机", "22795": "主暴病暴逆"}, "t": 3, "np": 0}, "c:弦+浮+紧": {"o": "浮紧弦脉总起来主外寒引动内饮、寒伤少阴、阳浮戴阳之证。浮紧为寒邪束表，弦为水饮内停或寒入少阴。两类病机常相兼为患：外寒束表则肺气不宣，水湿泛滥而为风水相搏；寒邪乘虚直入少阴，则逼水中之火飞越于上，成戴阳重症。其核心在于寒邪为患，或兼水饮，或兼虚阳浮越，病位涉及肺、脾、少阴。各段原文所示，浮紧弦脉总以寒邪为始动因素，或引动内饮，或伤及少阴，形成表里同病、虚实夹杂之候，故其主病机可归纳为外寒束表、寒伤少阴、水饮内停、阳浮戴阳四类，彼此关联，反映了寒邪致病的不同层次与转归。", "c": [{"name": "主外寒束表", "desc": "浮紧为寒邪袭表之象，原文见身热不扬、微有恶寒，或遍体浮肿而苔白腻，皆因寒邪由皮毛而入，束于表分，卫阳被遏，故脉浮紧并见。"}], "n": {"主外寒束表": 2}, "a": {"51": "主外寒束表", "416": "主外寒束表"}, "t": 2, "np": 0}, "pc:六+数+洪+长": {"o": "六·数洪长脉总属热盛邪实之象。数主热急，洪主热盛，长主邪气有余，三者相合，突出热毒壅盛、邪气亢盛之病机。所主病机主要有三类：一为热盛，二为邪气有余，三为阳明热证。其中热盛是核心，邪气有余强调正邪交争之剧烈，阳明热证则指明病位。各类之间相互关联：热盛则脉数洪，邪气盛则脉长，热邪壅盛于阳明则见洪数而长。临床见此脉，多提示实热证，治宜清热泻火解毒，兼顾透邪。", "c": [{"name": "主热盛", "desc": "数脉主热，洪脉为热盛之象。原文'洪为热盛，数为热急'，且见'发寒热，耳前后颊车红肿，渐及满头红大如斗，昏愦谵语'等热毒壅盛之症，故洪数相合主热邪炽盛。"}], "n": {"主热盛": 2}, "a": {"6277": "主热盛", "24646": "主热盛"}, "t": 2, "np": 0}, "c:细+微+紧": {"o": "紧细微脉总起来主燥金收敛、正虚邪结与正虚感邪三类病机。其脉象以紧、细、微复合为特征：紧主收敛、主寒、主痛、主积；细主津液不足、正气渐伤；微主阳气衰微、鼓动无力。从原文看，紧细微脉既可应秋燥金之气，表现为皮肤皴揭启裂，反映燥邪伤津、腠理闭密；又可主积与寒痛，因寒邪与气血搏结、久积成块，而细微示正虚、积块深伏；还可主正虚感邪，紧数微细并见说明元气亏虚而外受风寒，正不胜邪。三类之间，燥金收敛侧重外邪与津液，正虚邪结侧重内伤积块，正虚感邪侧重表里同病，但共同病机均离不开“紧敛”与“细微”所反映的收敛、虚损之象。", "c": [{"name": "主燥金收敛", "desc": "紧细微脉应秋燥金之气。原文以“燥金主于紧敛”释之，紧为收敛之象，细为津液不充，微为阳气不布，故脉见紧细而微，主燥邪伤津、皮肤皴揭启裂之候。"}], "n": {"主燥金收敛": 2}, "a": {"19395": "主燥金收敛", "25139": "主燥金收敛"}, "t": 2, "np": 0}, "c:弦+紧+实": {"o": "弦紧实脉总起来主实证，具体包括气滞、寒凝、邪结三类病机。弦主厥阴气滞，紧主寒凝收引，实主邪结有形，三者相兼，反映寒凝气滞、结聚不散之候。原文'寒热之后，厥阴气滞，小腹痞痛，归于右偏，脉弦紧实者，宜疏'，说明此脉主邪实壅盛，治宜疏达行气散结。三类病机相互关联：气滞可致寒凝，寒凝加重气滞，气滞寒凝日久则邪结有形，共同构成实证的病理基础。", "c": [{"name": "主气滞", "desc": "弦脉主厥阴气滞，原文'弦主厥阴气滞'，寒热之后厥阴气滞，小腹痞痛归于右偏，脉弦紧实，说明气机郁滞不通，结聚不散，属实证可疏。"}], "n": {"主气滞": 1}, "a": {"6654": "主气滞"}, "t": 1, "np": 0}, "pc:左+弦+涩+濡": {"o": "左弦涩濡脉（此处实际为右濡左不弦而涩）总起来主脾虚湿滞、营血不足、气机不畅及气陷下痢之病机。右濡为脾虚湿滞，左涩为营血不足、气机不畅，二者相合，反映暑湿伤脾、气弱不化、冷物阻滞中焦、脾阳既虚不能达邪的病理状态。其核心在于脾阳虚弱，运化失职，湿滞中焦，气血生化不足，营血亏虚，气机因虚而滞，进而气陷于下，发为下痢。各类病机之间相互关联：脾虚湿滞为始动因素，导致营血不足与气机不畅；气机不畅又加重湿滞，营血不足使脉道涩滞；最终脾阳不达，气陷下痢。故治疗先培补，清升则浊降，以疏化之品主之。", "c": [{"name": "主脾虚湿滞", "desc": "右脉濡为脾虚湿滞之象。原文述暑湿伤脾，气弱不化，冷物阻滞中焦，舌黄而腻，脉右濡，正合脾阳既虚、湿邪内滞之机，故濡脉主脾虚湿困、运化失职。"}], "n": {"主脾虚湿滞": 1}, "a": {"6703": "主脾虚湿滞"}, "t": 1, "np": 0}, "c:滑+大+平": {"o": "滑大平脉在此段中总起来主痰湿内蕴、邪势尚盛，并示转机之象。滑脉主痰湿，大脉主邪盛，二者相合，反映痰湿与邪气交结为患。然二诊时脉滑大稍平，说明经升泄之法后，陷里之邪略得升散，脾之清气稍得升举，痰湿与邪势均较前减轻，故脉象转和，为疾病向愈之转机。三类病机相互关联：痰湿与邪盛是病本，转机是治疗后邪减湿化之动态变化，共同体现滑大平脉在病程中的辨证意义。", "c": [{"name": "主痰湿", "desc": "脉滑主痰湿内蕴。原文'脉滑大稍平'，并明言'滑主痰湿内蕴'，说明滑脉反映体内痰湿之邪。二诊时滑象稍平，示痰湿略减，但仍未全消，故滑脉主痰湿为病机之一。"}], "n": {"主痰湿": 1}, "a": {"7439": "主痰湿"}, "t": 1, "np": 0}, "c:弦+滑+和": {"o": "弦滑和脉总起来主气机郁滞、痰湿内停及肝胃不和。弦主气郁，滑主痰湿，二者相兼，常因气郁津凝而生痰湿，痰湿内阻又加重气滞，形成恶性循环。原文脉象稍退、柔和，伴胀满舒、能安谷，说明郁解湿化，胃气渐和。三证相互关联，气郁为始动，痰湿为病理产物，肝胃不和为病位所在，治疗当以调和肝胃、行气化湿为要。", "c": [{"name": "主气郁", "desc": "弦脉为气机郁滞之象，原文左寸关弦象稍退，说明肝气郁结渐解。气郁则胀满，脉弦反映气机不畅，经调和肝胃后弦减，证实弦主气郁。"}], "n": {"主气郁": 1}, "a": {"7866": "主气郁"}, "t": 1, "np": 0}, "c:小+弱+促": {"o": "弱小促脉总起来主气血两虚、营卫俱损而兼虚中夹滞。其脉形小弱，为气血不足、营卫两伤之本质；促为数而时止，示虚中夹滞，因疟久不止、辛散过投，正虚而邪滞未净。三者相互关联：气血两虚是基础，营卫俱损是具体表现，虚中夹滞是兼夹病机。故治疗用补中益气汤补益中气、升举清阳，使营卫调和，则脉象可复。", "c": [{"name": "主气血两虚", "desc": "脉弱小促中‘小弱’为气血不足之象。原文‘脉弱小促’直接点明小弱主气血两虚，且疟久不止、辛散过投致卫伤营伤，营卫俱损，故脉形弱小，反映气血亏虚本质。"}], "n": {"主气血两虚": 1}, "a": {"11317": "主气血两虚"}, "t": 1, "np": 0}, "c:滑+缓+长": {"o": "缓滑长脉总起来主气血充盛、脾胃健运，属平脉范畴，非病脉。其缓为胃气之和，滑为营血之充，长为气机之畅，三者相合，反映后天脾胃健运、气血生化有源，故虽年五十而天癸不衰、肌肤润泽。原文所载左寸关带弦数，仅为肝郁化热之微兆，与多产、微带相关，属兼见之象，不改变全脉平顺之本质。三类病机中，气血充盛与脾胃健运互为因果，共成平脉之基；肝郁化热则为兼夹之微变，提示体质虽盛而略有郁热倾向。", "c": [{"name": "主气血充盛", "desc": "脉缓滑而长，缓为胃气充足，滑为营血旺盛，长为气机调畅，故主气血充盛。原文谓‘缓滑而长为气血充盛、脾胃健运之象’，且年五十而天癸不衰、肌肤似三十许人，正是气血有余之征。"}], "n": {"主气血充盛": 1}, "a": {"13454": "主气血充盛"}, "t": 1, "np": 0}, "c:沉+软+结": {"o": "沉软结脉总属肝郁气结、郁热挟痰之候。沉主里，软主气机不畅，结示郁滞，合而观之，其病机核心为肝气郁结，气郁日久则生热，热灼津液则凝痰，痰热互结，阻滞中焦。原文脉沉弦而软滑，正是郁、热、痰三者交织之象。误用温补，更助热凝痰，致痞满日增、肌肉渐消。故本脉所主，以肝郁气结为始，郁热挟痰为变，误补凝痰为加重之因，三者层层相因，总不离气郁痰热之病机。", "c": [{"name": "主肝郁气结", "desc": "脉沉软，沉主里、软主气机不畅，原文'脉沉弦而软滑'，沉软并见，提示肝气郁结于里，气机不得宣通，故见腹胀如痞、时欲冲逆吐酸。"}], "n": {"主肝郁气结": 1}, "a": {"14006": "主肝郁气结"}, "t": 1, "np": 0}, "c:滑+缓+迟": {"o": "缓滑迟脉总主痰湿内盛、胃阳素弱、肝风乘脾、积热伤津之机。缓滑为湿盛痰聚，耎迟为胃阳不足，左缓滑映肝木乘虚，久则痰湿化热、风阳内动、胃津受灼。四类病机相互关联：胃阳弱则湿痰生，痰湿盛则肝木乘，温药误投则积热伤津，形成痰、湿、虚、热交织之候。脉象缓滑迟并见，正映痰饮踞中、肝升太过而胃降无权，久则气阻血瘀、元虚散漫，故总以痰湿为枢，虚实寒热错杂为要。", "c": [{"name": "主湿痰", "desc": "脉缓滑为湿盛痰聚之象。原文述‘身躯素厚，湿盛为痰’，缓脉主湿，滑脉主痰，湿痰踞中则脉见缓滑。痰饮本水谷悍气，久积不化，故脉象映痰湿内盛之机。"}], "n": {"主湿痰": 1}, "a": {"14218": "主湿痰"}, "t": 1, "np": 0}, "pc:右+小+弱+缓": {"o": "右·小弱缓脉总属虚候，以气虚为核心，兼见脾虚阳浮、气血两虚与阳陷虚泻。右脉洪缓无力，非热非实，乃脾胃气虚、虚阳外浮之假洪；左脉缓小而弱，为气血不足、脉道不充。缓为气弱，小弱为不足，无力为鼓动衰微，四类病机皆围绕正虚展开：脾虚则阳浮于外，气血虚则脉道失充，阳陷则清阳不升而便泻食少。诸类之间以气虚为共同基础，脾虚阳浮偏于中焦气浮，气血两虚偏于左脉血少，阳陷虚泻偏于中阳下陷，实为一虚之不同侧重。此脉忌见洪大实数，若误作实热而发散或寒凉，必致虚上加虚。", "c": [{"name": "主气虚", "desc": "右脉洪缓无力，左脉缓小而弱，皆气虚之象。缓为气弱不鼓，小弱为气血不足，无力为正气不能推动。患者形肥色淡紫、体倦食少、便泻，皆中气亏虚之征，故脉见缓小弱而无力。"}], "n": {"主气虚": 1}, "a": {"15150": "主气虚"}, "t": 1, "np": 0}, "c:细+沉+硬": {"o": "沉细硬脉总起来主沉寒痼冷、气血虚衰、里实坚结三类病机。沉主里，细为气血虚，硬为寒凝坚结，三者相合，揭示虚寒为本、寒凝为标、里实为果的病理链条。原文产后气血交虚，积寒在腹，致胸腹胀满而坚、足冷过膝、咳喘不食，正是虚寒内盛、寒凝气机、坚结于里之象。三类病机中，气血虚衰是基础，寒凝坚结是核心，里实壅塞是结果，彼此关联，共同构成沉细硬脉的复合病机。", "c": [{"name": "主寒凝", "desc": "脉沉细而硬，硬为寒凝坚结之象。原文见产后积寒在腹，胸腹胀满而坚，足冷过膝，干呕不食，咳喘不能卧，皆沉寒痼冷蟠结三焦所致，故硬脉主寒邪凝滞、气血结聚不通。"}], "n": {"主寒凝": 1}, "a": {"16238": "主寒凝"}, "t": 1, "np": 0}, "c:滑+涩+弱": {"o": "涩弱滑脉总属虚中夹实之象。涩主血少行滞，弱主气虚不充，滑主湿痰水饮。三脉并见，提示气血两虚为本，湿滞水停为标。产后气血亏耗，脾虚运化无力，水湿内停，故见便泻、跗浮、苔滑；胃气未复则嘈杂少谷。虚象与湿滞并存，治当分利水湿兼顾扶正。", "c": [{"name": "主气血两虚", "desc": "脉涩主血少行滞，弱主气虚不充。原文'产后四月，脉涩弱'，正合产后气血两亏，涩弱并见提示气血不足且运行不畅。"}], "n": {"主气血两虚": 1}, "a": {"17058": "主气血两虚"}, "t": 1, "np": 0}, "c:细+微+软": {"o": "微细软脉总属虚证，主气营大亏。其脉象由微、细、软三象复合而成，分别对应阳气衰微、阴血不足、气营两亏，三者相互关联，共同反映气血阴阳俱虚之病机。原文以“脉微细软”为据，断为“气营大亏，非补不可”，强调虚证当补。微主阳衰，细主阴亏，软主气营两亏，三者从不同侧面揭示虚损本质，但总不离气血阴阳亏虚、脉道失充与鼓动无力。临床见此脉象，多提示产后、久病等耗伤气血之候，治宜温补培元，不可妄攻。", "c": [{"name": "主阳气衰微", "desc": "脉微为阳气衰微之象。原文指出“微主阳气衰微”，阳气虚衰则脉道鼓动无力，故见脉微。产后腹痛、形神削夺等症亦反映阳气不足，温煦失职，故脉微主阳气衰微。"}], "n": {"主阳气衰微": 1}, "a": {"18181": "主阳气衰微"}, "t": 1, "np": 0}, "pc:左+大+浮+散": {"o": "左·大浮散脉总属气机浮越、脏气失守之象。其脉大而浮散，既主正气亏虚、气不内守，又主气逆上浮、升降失常，并可因色脉相失而提示病邪逆顺之变。三类病机相互关联：虚为根本，气逆为变动，色脉相失为诊察要点。原文以“有诸内者形诸外”为纲，强调脉象随脏气变动而主不同病机，浮散大脉正是脏气外浮、不能内藏的表现，故临床当结合五色合参，以辨虚实逆顺。", "c": [{"name": "主虚", "desc": "浮散脉象，浮为气虚外浮，散为气耗不敛，故主正气亏虚。原文虽未明言，但浮散之脉与“有诸内者形诸外”相参，提示脏气不足、不能内守，脉气浮散于外，属虚象。"}], "n": {"主虚": 1}, "a": {"18621": "主虚"}, "t": 1, "np": 0}, "pc:左+数+沉+紧": {"o": "左·数沉紧脉总属虚实夹杂、寒热错杂之候。其左脉沉细欲无，主清阳下陷、正气虚馁；右脉沉紧而数，主瘀血受寒、热郁于内。三者相互关联：产后用力过度致清阳下陷为本虚，瘀血受寒为标实，误服热药更添热郁，形成虚、瘀、寒、热交织之局。脉象上，左脉细弱示正虚，右脉紧数示邪实，故不可单纯作热或作寒论，当结合病史，辨其清阳下陷、瘀血受寒、热郁于内之复合病机。", "c": [{"name": "主清阳下陷", "desc": "左脉沉细欲无，为清阳下陷、正气虚馁之象。因临盆用力过甚，上焦清阳下陷，故产后发寒热。脉沉细无力，提示正气不足、清阳不升，属虚陷之机。"}], "n": {"主清阳下陷": 1}, "a": {"20375": "主清阳下陷"}, "t": 1, "np": 0}, "c:弦+沉+硬": {"o": "弦硬沉脉总起来主肝经病变，以肝郁气结为核心，气郁化火伤阴则致血虚火旺，肝木亢盛则克伐脾土，形成木旺克土、脾胃虚弱之候。三类病机相互关联：肝郁气结为始动因素，气郁日久化火伤阴，故见血虚火旺；肝旺则乘脾，导致脾胃健运失职。原文左脉弦硬而沉，右脉弦而无力，正是肝病及脾的典型表现。故弦硬沉脉所主病机不离肝郁、火旺、血虚与脾虚，但以肝郁气结为关键，他证皆由此衍生。", "c": [{"name": "肝郁气结", "desc": "弦为肝脉，沉主里，弦硬沉提示肝气郁结于里。原文左脉弦硬而沉，明确指出肝气郁结，气机不畅，故见胁疼等症。"}], "n": {"肝郁气结": 1}, "a": {"20514": "肝郁气结"}, "t": 1, "np": 0}, "c:细+紧+实": {"o": "紧实细脉总起来主邪气内结而正气未散之候。其脉象紧实反映邪实内结，细象则示收敛之机尚存，故虽病重而脉未散越，预后多生。与浮大脉之邪张正脱、大而止脉之失血脉断形成鲜明对比，说明紧实细脉所主病机关键在于邪实与收敛并存，非正气外越或虚脱之象。临床见此脉，当知邪虽盛而正未大伤，治宜祛邪为主，兼顾收敛，不可误作虚脱而妄投补涩。", "c": [{"name": "主邪结可生", "desc": "紧实细脉主邪气内结而正气未散。原文“中恶腹大，脉紧实细者，生”，紧实为邪气内结，细则尚存收敛之象，邪虽盛而脉未散越，故预后良好。此脉象反映邪实与收敛并存，非正气外脱之候。"}], "n": {"主邪结可生": 1}, "a": {"21147": "主邪结可生"}, "t": 1, "np": 0}, "pc:寸+微+弱+迟": {"o": "寸·微弱迟脉总属虚寒与气血不足之象。迟脉主阳气不足，微弱主气血俱虚，寸部候上焦心肺，寸脉微弱则心肺气虚、气血生化无源。三者相合，反映阳气虚衰、气血亏虚、冲任空虚的整体病机。原文以此脉象断“绝子不产”，说明其病机核心在于虚寒与气血亏虚导致胞宫失养、生殖功能低下。三类病机相互关联：虚寒为阳气不足之因，气血虚为微弱之果，不孕则是虚寒与气血亏虚共同作用下的具体病证，层层相因，总归于虚。", "c": [{"name": "主虚寒", "desc": "原文“脉迟寸俱微弱”，迟为阳气不足，微弱为气血俱虚，寸候上焦心肺，心肺气虚则阳气不能温煦，故脉迟而弱，主虚寒之证。"}], "n": {"主虚寒": 1}, "a": {"21204": "主虚寒"}, "t": 1, "np": 0}, "pc:尺+大+浮+紧": {"o": "尺·大浮紧脉在此段中主要体现浮大与沉小的吉凶对比，其总病机围绕邪正盛衰：浮大脉在伤寒热盛时主邪实热盛、正气抗邪，为生候；但汗后见浮大则主正虚不敛、邪陷为凶。温病脉大疾者生，细小难得者死，示正能抗邪则生，正不胜邪则死。故该脉所主病机可归为邪盛热实、正虚邪陷、正不胜邪三类，核心在于脉象与病机、病程的相应与否，以判吉凶。", "c": [{"name": "主邪盛热实", "desc": "伤寒热盛时脉浮大，为邪气实而正气能抗，脉象浮大反映热邪外达、气血涌盛，故原文以浮大者为生，示邪有外透之机。"}], "n": {"主邪盛热实": 1}, "a": {"21824": "主邪盛热实"}, "t": 1, "np": 0}, "pc:尺+大+浮+软": {"o": "尺部大浮软脉在《脉经》此段中，主要围绕伤寒温病过程中脉象浮大与沉小的吉凶判断展开。其总病机可归纳为三类：邪盛正抗、汗后正伤、正虚邪陷。浮大之脉在热盛时主邪有外达之机、正气尚能抗邪，为吉；但若汗后见浮大，则主正气外浮不敛、津伤阳越，为凶。沉小之脉在汗后主邪退正安，为吉；而在热盛或温病中见沉小细微，则主正虚不能抗邪、邪气内陷，为危候。三类之间以正邪盛衰为枢机：同一脉象在不同病程阶段吉凶迥异，关键在于正气能否抗邪及邪气能否外达。浮大软脉本身非独主一病，须结合病程、汗出与否及兼脉综合判断，体现了中医脉诊动态辨证的特点。", "c": [{"name": "主邪盛正抗", "desc": "伤寒热盛脉浮大者生，温病脉大疾者生，皆因邪气虽盛而正气能奋起抗邪，脉象浮大有力，示邪有外达之机，正能胜邪，故为吉兆。"}], "n": {"主邪盛正抗": 1}, "a": {"21824": "主邪盛正抗"}, "t": 1, "np": 0}, "pc:寸+数+小+紧": {"o": "寸·数小紧脉在《伤寒论》胸痹条文中，总属阳微阴弦、痰饮痹阻之候。其病机核心为胸阳不振、寒饮搏结、痰饮痹阻胸中。寸脉沉而起，主胸阳不足、饮邪内停；关脉小紧数，主中焦寒饮搏结、气机紧束而迫。三者相互关联：胸阳不振为病之本，寒饮搏结为病之标，痰饮痹阻为病之果。脉症合参，见喘息咳唾、胸背痛、短气，故以栝蒌薤白白酒汤通阳散结、行气祛痰。此脉所主，总在阳虚阴盛、痰饮为患，非单纯热证或虚证。", "c": [{"name": "主胸阳不振", "desc": "寸脉沉而起，沉为阳气不布，胸阳不振，故见喘息咳唾、胸背痛、短气。原文以寸脉沉示胸阳不足，饮邪内停，属阳微阴弦之候。"}], "n": {"主胸阳不振": 1}, "a": {"22069": "主胸阳不振"}, "t": 1, "np": 0}, "c:细+实+伏": {"o": "细伏实脉总起来主邪实内闭、气逆脉道不行之证，尤以暴痛为典型。其脉虽沉伏细涩，貌似极虚，但细察必有梗梗然弦紧之意，为寒邪阻遏阳气、气为邪逆所致，故属实证而非虚候。原文强调脉忽细伏者多实邪，脉本微弱者方为虚邪，示人暴痛脉伏不可误认虚脱，当辨形气。两类病机实为一体：实邪为因，寒痛为果，均以脉道不通、邪气内闭为核心，临床须于沉伏中细辨弦紧之象，以别虚实。", "c": [{"name": "主实邪", "desc": "原文指出暴痛之极每多沉伏细涩，最似极虚，实因气为邪逆、脉道不行而沉伏异常，乃邪实之脉；沉伏中细察必有梗梗然弦紧之意，为寒邪阻遏阳气所致。故脉忽细伏者多实邪，强调不可误认虚脱。"}], "n": {"主实邪": 1}, "a": {"23390": "主实邪"}, "t": 1, "np": 0}, "c:大+紧+急": {"o": "大紧急脉总起来主阴寒内盛、虚阳外浮之格阳证。其脉象特征为大、紧、急：大因虚阳外浮，紧因寒邪内盛，急因阳气欲脱。原文以“渴甚面赤，扇扇不知凉，饮冰不知冷”等症，揭示内真寒外假热之病机，故以大紧急脉为凭，断为格阳，治以温中回阳。此脉虽仅一段，然其病机明确，即阴寒格拒阳气于外，属危重之候。", "c": [{"name": "主格阳", "desc": "脉大紧而急，大则虚阳外浮，紧急为寒邪内盛，虚阳被格拒于外，故见渴甚面赤、扇扇不知凉、饮冰不知冷，此乃格阳之象。腹痛甚、时时躁烦，为阴寒内盛、阳气欲脱之候。"}], "n": {"主格阳": 1}, "a": {"24440": "主格阳"}, "t": 1, "np": 0}, "pc:尺+沉+虚+涩": {"o": "尺部沉虚涩脉总属阴血津液枯竭、内伤噎隔之候。沉主里，涩主血少津枯，虚则不足，合而示内伤日久、阴血耗损。原文以沉涩为内伤噎隔主脉，分候脏腑：左寸心血枯、左关肝血竭、尺肾水虚、右关脾阴绝、胃汁干而肠结，层层推演阴血枯竭之机。三类病机相互关联：阴血枯竭为根本，津亏肠结为阴津枯涸所致之标，内伤噎隔则是阴血枯竭、津亏肠结共同形成的病证总括。故本脉总主内伤虚损、阴血津液亏竭，以噎隔、便秘等为常见表现。", "c": [{"name": "主阴血枯竭", "desc": "沉主里，涩主血少津枯。原文以沉涩为内伤噎隔主脉，分候寸关尺及脾胃，见心血枯、肝血竭、肾水虚、脾阴绝、胃汁干，皆阴血津液枯竭之象，故沉虚涩脉主阴血亏虚。"}], "n": {"主阴血枯竭": 1}, "a": {"24721": "主阴血枯竭"}, "t": 1, "np": 0}, "pc:右+沉+紧": {"o": "右·沉紧脉总属里寒实证，以寒邪内侵、气机凝滞为核心。沉主里，紧主寒主痛，右脉候脾胃，故其病机多围绕中焦寒凝展开。具体而言，或寒与食积并结，或气郁食滞，或寒凝阳虚，或寒瘀互结郁而化热，或寒湿内伏。各类之间以寒邪为共同基础，但因兼邪不同（食、气、瘀、湿）及体质差异（阳虚、气陷）而呈现不同证候。紧脉虽主寒，但在大气下陷、实热内郁时亦可出现沉紧有力，乃气陷不能鼓脉所致，提示不可拘泥于寒。总之，右沉紧脉主里寒、气滞、积结，治多温通、运化、升陷，需结合兼脉及症候细辨。", "c": [{"name": "主寒积中焦", "desc": "右脉沉紧，沉主里、紧主寒主痛，右候脾胃，故主寒邪与食积并结中焦。原文见腹中频痛、呕吐酸水、下白冻、里急后重、舌苔白腻等，皆寒湿积滞内停、气机不通之候，治宜温中运食、温通定痛。"}, {"name": "主气郁食滞", "desc": "右脉沉紧时一止，沉主里，紧主气郁，止为结代。因焦虑太甚，心脾郁结，食滞不化，气机郁滞而脉沉紧时止。原文见夜不成眠、饮食减少、面色惨然，非单纯归脾汤所能治，当疏气导滞。"}, {"name": "主寒凝血瘀化热", "desc": "右脉数沉紧，沉主里，紧主寒，数主热，合见提示寒瘀互结于里，郁而化热，热不得外达；兼左脉沉细欲无，为正气虚馁、清阳下陷。原文因产后努力、瘀血受寒、误服热药，致寒热错杂、大气下陷。"}, {"name": "主寒湿内伏", "desc": "右脉沉紧，沉主里，紧主寒，为寒湿内伏之象。原文论寒湿痢，左浮紧为太阳寒湿，右浮大为阳明寒湿，寒湿内伏则脉沉紧，少阳受邪则弦紧，说明沉紧主寒湿深伏于里、气机壅滞。"}], "n": {"主寒积中焦": 2, "主气郁食滞": 1, "主寒凝血瘀化热": 2, "主寒湿内伏": 2}, "a": {"2894": "主气郁食滞", "15622": "主寒积中焦", "15663": "主寒湿内伏", "15874": "主寒积中焦", "19485": "主寒凝血瘀化热", "19486": "主寒凝血瘀化热", "25001": "主寒湿内伏"}, "t": 7, "np": 0}, "pc:右+沉+伏": {"o": "右沉伏脉总主病机为邪阻气闭、阳气不达，或肾虚火不归元。其类别包括肾虚火浮、气闭、痰格、热积内伏及瘀血。肾虚火浮属虚，因尺脉沉伏、脉微无力，虚火浮游；气闭、痰格、热积内伏、瘀血属实，因邪阻脉道，气血不畅，脉沉伏不起。实者多兼滑大、弦数等象，虚者多兼微细。沉伏一脉，虚实皆可见，关键在兼脉与症：虚者温补，实者通利，不可一概而论。", "c": [{"name": "主肾虚火浮", "desc": "右尺沉伏不起，脉微无力，为肾虚阳气不足，虚火不归原而浮游。原文谓“尺脉沉伏者，肾虚也”，热上下循环、足底热甚，乃肾火浮游之象，故沉伏主肾虚火不归元。"}, {"name": "主气闭", "desc": "左脉沉伏，伴右滑大有力，为气机郁闭于下。原文谓“气闭下焦”，故二便不利、气逆呕吐。沉伏示气闭于内，非虚寒，经吐痰通便后左脉起，说明气通则脉起。"}, {"name": "主痰格", "desc": "沉伏脉可因痰格中焦、气闭下焦而见。原文左沉伏、右滑大，断为“痰格中焦”，痰阻气机，脉道不利，故沉伏。痰去气通则脉平，说明沉伏为痰阻气闭之征。"}, {"name": "主热积内伏", "desc": "热积腹痛，脉反沉伏，按之良久应指劈劈。原文谓“热积内伏，脉反沉伏”，乃热邪深结，阳气不能外达，非虚寒。沉伏为实热内闭之象，与腹痛便结相应。"}], "n": {"主肾虚火浮": 2, "主气闭": 1, "主痰格": 3, "主热积内伏": 1}, "a": {"3606": "主肾虚火浮", "4228": "主肾虚火浮", "5979": "主痰格", "6104": "主痰格", "6273": "主痰格", "6398": "主气闭", "25067": "主热积内伏"}, "t": 7, "np": 0}, "pc:右+大+濡": {"o": "右·大濡脉总以濡主湿、右大主邪盛或中虚为纲，所主病机可归为湿、气虚阳衰、肝风内动、积劳内伤、暑湿疟五类。濡脉本主湿伤与气弱，右大则示邪盛于气分或脾胃受困；若右濡而左大，则左大主肝风震动，右濡主阳明中虚，形成肝风与中虚并见之候；若大而濡软无力，又为胃阴亏虚、吐伤津燥之象。诸类之间，湿与气虚常相兼，肝风与中虚每并现，积劳内伤则营气亏虚、脾土不足，暑湿疟则湿与热交蒸、邪正交争。总起来说，右·大濡脉以湿浊内蕴、气分邪盛或中阳不足为基础，可兼见肝风、津伤、食积等，病位多在阳明脾胃，涉及厥阴肝木，虚实夹杂，以湿、虚、风、积为要。", "c": [{"name": "主湿", "desc": "濡脉主湿，右大主邪盛于气分或脾胃。原文如暑风夹湿脉濡右大、食积化肿脉濡右大，皆因湿浊内蕴、脾运失职，湿性濡滞故脉濡，右大示邪盛或脾胃受困。"}, {"name": "主肝风内动", "desc": "左大右濡并见，左大主厥阴内风掀越，右濡主阳明中虚或络脉空虚。如暴中案脉左大右濡，内风掀越而中阳已虚；中络案脉左大右濡，肝风震动而阳明脉空。"}, {"name": "主积劳内伤", "desc": "右脉大而见濡，左部亦弱，无弦急之象，为积劳内伤、营气二亏、脾土不足、木失所养。如肝邪结痞案，脉大而濡为气虚湿滞，弱主营气亏虚，非肝木亢急实邪。"}, {"name": "主暑湿疟", "desc": "脉濡右大，濡主湿，右大主邪盛于气分，暑风夹湿，湿性濡滞，邪正交争，寒热如疟。原文暑风夹湿案脉濡右大，舌白中心嫩黄，渴饮溲数，皆暑湿内蕴之象。"}], "n": {"主湿": 1, "主肝风内动": 2, "主积劳内伤": 1, "主暑湿疟": 1}, "a": {"777": "主肝风内动", "5008": "主肝风内动", "6651": "主积劳内伤", "16743": "主暑湿疟", "16952": "主湿"}, "t": 5, "np": 0}, "pc:六+大+小": {"o": "大小脉总以脉形不匀、变动不居为特征，所主病机涵盖虫积、脾虚夹滞、邪祟、真阴不足四类。虫积与脾虚夹滞常相兼为患，脉大小不等反映气机紊乱、虚实错杂；邪祟则脉忽大忽小、忽沉忽浮，无定体可循，为神志受扰之象；真阴不足则见洪大有力，乃虚阳浮越之假象。四类之中，虫积、脾虚夹滞属内伤杂病，邪祟属外邪干扰，真阴不足属虚损，然其共同点在于脉象失其常度，或大小参差，或洪大无根，皆提示气血阴阳之平衡失调。临证需结合症候，辨其虚实真假，不可执一而论。", "c": [{"name": "主虫积", "desc": "脉大小不等，参以嗜肉、嘈杂、吐酸涎，为虫扰气机、阴阳错杂之象。虫动则脉气不匀，虫静则稍安，故脉大小不齐主虫积内扰。"}, {"name": "主脾虚夹滞", "desc": "脉大小不等提示脾胃虚实错杂、气机紊乱。脾虚不运则嘈杂思肉，肉入难化则气逆痛吐，脉象不匀正是脾虚夹滞、升降失司之象。"}, {"name": "主邪祟", "desc": "脉忽大忽小、忽沉忽浮，变动不居，无一定之形，非气血偏盛偏衰之常脉，乃邪祟凭附、扰乱神明之象。脉无定体，故谵妄终日，安神化痰诸剂不效。"}, {"name": "主真阴不足", "desc": "六脉洪大有力，为真阴不足、龙雷之火妄作，故脉洪大而数。洪大为假阳乘之，非真阳盛实，不可误用知柏地黄汤。脉之微缓为有神之常，反衬疾乱变常之病机。"}], "n": {"主虫积": 1, "主脾虚夹滞": 2, "主邪祟": 1, "主真阴不足": 1}, "a": {"3674": "主虫积", "6201": "主脾虚夹滞", "6496": "主脾虚夹滞", "17360": "主邪祟", "18424": "主真阴不足"}, "t": 5, "np": 0}, "pc:寸+数+促": {"o": "寸部促数脉总属热盛，但具体病机有实热、虚火、热壅肺气及气机不调之别。数脉主热，促脉示脉来数中一止、节律不匀，故促数并见首先反映热邪亢盛。若见于右寸，因寸部候肺，多主风温等温邪壅肺、误汗劫津，热壅肺气而气机不调，甚则危候；若见于两寸而伴形体日损、咳嗽吐痰，则属虚证，为烦劳动阳、虚火上炎、胃阴亏虚之象。可见促数脉所主之热有虚实之分：实者热壅肺气，虚者虚阳浮越；而气机不调则贯穿于热盛诸证之中。临证须结合寸部脏腑分候及全身症状，辨其虚实，不可一概而论。", "c": [{"name": "主虚火", "desc": "促数脉亦见于虚证，因虚阳浮越、虚火上炎而致。原文两寸促数，注为‘促为阳脉，数主热’，但患者形体日损、咳嗽吐痰，乃‘烦劳动阳、虚火上炎’，非实火，属胃阴亏虚、虚阳浮越之象。"}, {"name": "主热壅肺气", "desc": "右寸候肺，促数不调提示热邪壅肺、气机不畅。原文风温误用温散，邪热壅肺，治节不行，故脉促数不调；温邪内陷、肺热壅盛；风温之邪郁于肺卫、误用温散劫津，均见右寸促数。"}], "n": {"主虚火": 1, "主热壅肺气": 3}, "a": {"896": "主虚火", "13030": "主热壅肺气", "14134": "主热壅肺气", "14427": "主热壅肺气"}, "t": 4, "np": 0}, "c:浮+空": {"o": "浮空脉总属虚候，以正虚为本，浮为气浮于外，空为脉道不充。其病机主要有四：一为气虚，诸部脉虚，脏腑气弱；二为阴血亏虚，脉道失充，多见于下焦阴亏或热病伤阴；三为虚阳外浮，阴不制阳，阳无所附，可见虚性寒热或温病邪热外浮；四为邪实正虚，痰热、表邪壅盛而元气已衰，脉兼弦滑数而中空。四类之间，气虚与阴血亏虚为根本，虚阳外浮多由阴虚或气虚发展而来，邪实正虚则为虚体受邪、虚实夹杂之变。总以虚为本，或纯虚，或虚中夹实，皆以浮空为共同脉象。", "c": [{"name": "主气虚", "desc": "浮空脉以浮为气、空为虚，总属气虚。原文明言脉浮而空，右寸虚为肺气不足，右关虚为中气不足，左寸虚为心气不足，左关虚为肝胆气弱，两尺虚为肾气不足，诸部皆虚，故主气虚眩晕，伴气短乏力等症。"}, {"name": "主阴血亏虚", "desc": "浮空脉按之中空，主阴血亏少，脉道不充。原文左部空浮为阴血亏虚、邪热外浮；两寸脉浮而空，因努挣伤气、阴乘阳位，关尺微细为下焦阴亏，浮空非表邪，乃内伤虚损、阴阳不相维系之象。"}, {"name": "主虚阳外浮", "desc": "浮空脉浮取即得而中空，为虚阳外浮、阴不制阳之候。原文温病十二天，左脉空浮，系邪热外浮而阴分已伤；便后寒热，寸脉浮空，为阴乘阳位、阳复胜阴之虚性寒热，非外感表邪，皆虚阳浮动所致。"}, {"name": "主邪实正虚", "desc": "浮空脉可兼见弦、滑、数等，主邪实壅滞而元气已虚。原文左空浮、右洪滑数，为痰热内闭而阴伤；太阳少阴合病，脉浮空无力，为表邪未解而肾阳已衰；浮空弦脉亦主邪实壅肺、元气虚衰，形成虚实夹杂之局。"}], "n": {"主气虚": 1, "主阴血亏虚": 1, "主虚阳外浮": 1, "主邪实正虚": 1}, "a": {"1966": "主邪实正虚", "3450": "主阴血亏虚", "22941": "主虚阳外浮", "24801": "主气虚"}, "t": 4, "np": 0}, "c:细+空": {"o": "细空脉总属虚候，以阴血亏虚、精血衰少为基本病机。细主阴血不足，空主脉道不充、气不摄固，故见精伤于下、气耗于上之劳怯重病。若兼弦急，则虚中夹实，阴血亏而湿痰瘀血内滞，气机逆乱；若兼数，则阴虚火旺，虚热内生，津血耗损。各类之间以正虚为本，或气不固，或夹实邪，或化虚热，皆由阴血亏虚演变而来，病位涉及少阴、中焦，甚则形神衰败。", "c": [{"name": "主精血亏虚", "desc": "细为阴血不足，空为脉道不充、精血衰少。原文见左脉细、右脉空，伴色夺神夭、声嘶，断为精伤于下、气不摄固；又左脉空细、细空，伴神情困倦，皆属阴血亏虚之象。"}, {"name": "主虚中夹实", "desc": "细空示正虚，若兼弦急等脉，则虚中夹实。原文左脉空细或细空，右脉弦急，伴呃忒、呕恶、便溏黑，为阴血亏虚而湿痰瘀血内滞，邪从上出不下行，气机逆乱，属虚波暗起之逆症。"}], "n": {"主精血亏虚": 1, "主虚中夹实": 2}, "a": {"824": "主精血亏虚", "4673": "主虚中夹实", "9098": "主虚中夹实"}, "t": 3, "np": 0}, "pc:两+弦+涩": {"o": "弦涩脉总属气滞血瘀、虚实夹杂之候。弦为气机郁滞，涩为血行不畅，两脉合见，提示气血交病，气滞与血瘀互结。所主病机主要有四类：血瘀、气滞、虚损、络阻。血瘀与气滞常相因为病，气滞则血瘀，血瘀加重气滞；虚损多为本虚，如肾虚精亏、血虚不荣，常与瘀滞并存，形成本虚标实；络阻为气血涩滞于络脉，表现为疼痛、结块。诸类之间相互关联，总以气血不和为核心，病位涉及肝、脾、肾及络脉，病情多复杂，需细辨虚实主次。", "c": [{"name": "主血瘀", "desc": "涩脉主营血瘀滞，弦脉主气机郁滞，两脉合见则气滞血瘀互结。如案1任重受伤，营血瘀滞，呕血便黑，脉涩两关独弦，示肝脾瘀结；案3脘中气结成痞，少腹血聚成瘕，两脉弦涩，为气血交病。故弦涩脉主血瘀，常伴气滞。"}, {"name": "主气滞", "desc": "弦脉为气机郁滞之象，涩脉示血行不畅，气滞则血瘀，故弦涩并见主气滞血瘀。案3脘中气结成痞，弦为气结；案13脉弦主气机郁滞、络脉不和。气滞可致胀满、结块、疼痛，弦涩脉反映气机不畅为核心病机之一。"}, {"name": "主络阻", "desc": "弦主气机郁滞、络脉不和，涩主血行不畅，两脉合见则络脉瘀阻。案13肾虚络阻，腰间作痛，起坐方适，脉弦涩，说明络脉不通；案1瘀血阻络，腹中结块。故弦涩脉主络阻，表现为疼痛、结块等，病位在络脉。"}], "n": {"主血瘀": 1, "主气滞": 1, "主络阻": 1}, "a": {"7587": "主血瘀", "10989": "主气滞", "11016": "主络阻"}, "t": 3, "np": 0}, "pc:两+数+大": {"o": "两·数大脉总属邪热亢盛之象，所主病机以热盛、邪实、热陷惊闭为核心。数脉主热，大脉主邪盛，二者相合，提示热邪炽盛、气血壅滞、正气未衰。实热证中，或为暑湿热邪蕴结肠道，或为表里俱热、积蒸于里，或为食滞中焦、腑气不通，甚则邪入营分、热扰神明、动风惊闭。各段均见数大脉与热盛邪实证候相应，故治疗以清利祛邪为要。三类病机相互关联，热盛为根本，邪实为表现，热陷惊闭为热盛邪实之进一步发展，临证需结合兼症辨别热势深浅及传变趋势。", "c": [{"name": "主热盛", "desc": "数主热，大主邪盛，两脉数大总为热邪炽盛之象。原文如暑湿下痢、病后热又一旬等，均见数大脉，伴腹痛后重、肌灼等热象，示热势鸱张，正气未衰，故宜清利祛邪。"}, {"name": "主邪实壅盛", "desc": "大脉主邪气实而壅盛，数脉主热，合则邪热内壅。原文见脘腹胀痛拒按、便闭口渴、谵语手痉，为食滞中焦、腑气不通，邪实热盛，脉象与证相应，故称棘手。"}, {"name": "主热陷惊闭", "desc": "数大脉示邪热炽盛，有内陷之势。原文病后热又一旬，表里俱热，热势鸱张，小儿易动风惊搐，热闭心包则昏闭，故曰“惊闭最易”，此脉提示热邪有内陷惊闭之危。"}], "n": {"主热盛": 1, "主邪实壅盛": 1, "主热陷惊闭": 1}, "a": {"10943": "主热盛", "11124": "主热陷惊闭", "17567": "主邪实壅盛"}, "t": 3, "np": 0}, "pc:左+浮+软": {"o": "左·浮软脉总起来主气血虚衰，尤以气虚、血虚及气血俱虚为核心。其脉象以浮软无力为主，兼见沉弱而缓、浮虚按不应指、变动无常等特征。原文明言「脉不常，血气虚也」，浮软无力为血虚不充，沉弱缓为气虚阳弱，脉无定准则示气血虚极、正气不守。三类病机相互关联：气虚与血虚常并见，日久则气血俱虚、中气不固，形成虚损之候。下属大浮软脉更兼气虚湿盛、血虚有热，并可发展为气血俱亏、脾不统血，但总不离气血虚衰之本。", "c": [{"name": "主气虚", "desc": "左脉沉弱而缓，右脉浮软无力，续诊心肺脉浮虚按不应指，脾脉轻按阁指重按不足，皆示中气不足、气不内守。原文谓「脉不常，血气虚也」，沉弱缓为气虚阳弱，浮虚为气不内守，故主气虚。"}], "n": {"主气虚": 2}, "a": {"3615": "主气虚", "15216": "主气虚"}, "t": 2, "np": 0}, "pc:六+散+代": {"o": "散代脉总起来主热盛、肝风、邪盛与真虚四类病机。其脉象或促而歇止，或洪大而散，皆以脉来散乱、歇止不匀为特征。热盛则脉促，热灼阴伤而歇止；肝风则风火相煽，脉促而症见瞤动眩晕；邪盛则脉洪大，然按之必虚；真虚则元气下陷，脉散而气不敛摄。四类之间，热盛与肝风常相兼为患，邪盛与真虚亦互为因果，总属本虚标实、虚实夹杂之候，故散代脉所主非单一病机，而须结合脉势与症情辨其主次。", "c": [{"name": "主热盛", "desc": "原文见六脉皆促，或七八至一歇，或三四至一歇，促为阳盛热结兼歇止，示壮火烁阴。热盛于内，故脉数而促，歇止乃热灼阴伤、脉道不利所致。"}], "n": {"主热盛": 2}, "a": {"3559": "主热盛", "24007": "主热盛"}, "t": 2, "np": 0}, "pc:右+缓+急": {"o": "右缓急脉总属湿热郁蒸、气机失调之候。右缓为湿郁气分，左急为肝风内动，二者并见，反映湿浊阻遏气分、肝风内扰之病机。原文指出‘水谷酒腥湿热相并郁蒸，阻挠清气之游行’，致营卫循环失职、升降失司，故见忽热忽温、头中如裹、神识呆钝、肢节瘛痉、咳痰映红、便溏带血等症。四类病机中，湿热郁蒸为总因，湿郁气分与肝风内动为分属右左之具体机转，清浊相干则为共同病理结果。诸类相互关联，总以湿热郁阻气分、引动肝风、清浊升降失常为要，久延可入血分。", "c": [{"name": "主湿热郁蒸", "desc": "右缓左急并见，原文谓‘水谷酒腥湿热相并郁蒸’，症见忽热忽温、头中如裹、舌白糜腐、便溏带血，皆湿热郁阻气分、熏蒸三焦之象，故脉象缓急不调。"}], "n": {"主湿热郁蒸": 2}, "a": {"4559": "主湿热郁蒸", "4916": "主湿热郁蒸"}, "t": 2, "np": 0}, "pc:右+弦+洪": {"o": "右·弦洪脉总起来主气火亢盛、阴血内亏、虚阳浮越之病机。弦为肝逆，洪为气火亢盛，二者相合，既可见于肝气逆乱、气逆血上冲犯阳明之狂吐，又可见于劳瘵足三阴亏损、虚热无火、无根之火浮于外之证。其病机核心在于阴血亏虚、元气不摄，导致虚火妄动、气逆血涌；或脾胃先损，火土太旺而金水衰涸，血随火泛。各类之间相互关联：气逆血涌为标急之象，阴虚火浮为根本之因，脾肾亏损为传变之果，总属本虚标实、阴阳失调之候。", "c": [{"name": "主气逆血涌", "desc": "右脉弦洪，弦为肝逆，洪为气火亢盛，气逆血上，冲犯阳明，致狂吐之患。原文以逆流之水喻逆行之血，脉不安静、波涛不定，正示气逆血涌、防其壅逆之机。"}], "n": {"主气逆血涌": 2}, "a": {"12715": "主气逆血涌", "23196": "主气逆血涌"}, "t": 2, "np": 0}, "pc:尺+虚+小": {"o": "尺·虚小脉总属虚候，以阳气不足、气血亏虚为根本。其主病机可分三类：一为下焦虚寒，因尺脉候下焦，虚小则阳气衰微，不能温煦下肢，故见足胫寒、痿痹脚疼；二为虚损危候，虚小脉见于伤寒温病热盛之时，示正气不能抗邪，脉证相反，预后凶险；三为胃络损伤，尺弱寸强，下焦阳虚而虚阳上浮，致胃络受伤。三类病机皆以虚为本，或虚寒内生，或正虚邪陷，或虚阳上浮，总不离阳气与气血之亏虚。虚小脉与尺脉弱、细微等相类，均提示下焦阳气不足，但虚小更偏于脉形之细弱，主虚损之甚。", "c": [{"name": "主下焦虚寒", "desc": "尺脉虚小，阳气不足，下焦失于温煦，故见足胫寒、痿痹脚疼；尺脉弱亦主下焦冷、无阳气。虚小为阳气衰微之象，寒从下生，故主下焦虚寒诸证。"}], "n": {"主下焦虚寒": 2}, "a": {"21807": "主下焦虚寒", "21824": "主下焦虚寒"}, "t": 2, "np": 0}, "pc:左+滑+和": {"o": "左·滑和脉总起来主痰饮内停、气机不畅及痰气交阻三类病机，核心为痰与气。滑脉主痰，弦脉主气滞，和利示邪不盛、胃气尚和。痰饮内蕴可阻滞气机，气机不畅又可生痰，二者互为因果，终致痰气交阻，上扰胸膈。原文脉象和利中见滑、弦、动荡，正是痰气交阻之轻证，故仅觉胸膈不快。三类病机相互关联，以痰气交阻为归结，反映病位在胸膈，病情尚浅。", "c": [{"name": "主痰饮", "desc": "滑脉为痰饮内蕴之象，原文左脉和利而滑，滑主痰饮，说明体内有痰湿停聚。痰饮内停，阻滞气机，故见胸膈不快。滑而和利，示痰饮未至大实，尚属轻浅。"}], "n": {"主痰饮": 1}, "a": {"2920": "主痰饮"}, "t": 1, "np": 0}, "c:实+空": {"o": "空实脉（本案表现为芤涩并见）总起来主血虚兼瘀、络脉不和之病机。其脉中空边实，中空为芤，主血虚失充；来往不利为涩，主瘀血内阻。二者相合，形成血虚与瘀血并存的虚实夹杂证。血虚则诸经失养，瘀阻则胃络震动，故见络脉不和。治疗上不可堵截，宜用和络之法，使血行而不伤正。三类病机相互关联：血虚为本，瘀血为标，络脉不和为果，共同构成该脉的完整病理内涵。", "c": [{"name": "主血虚", "desc": "脉中空边实，中空为芤脉之象，主血虚失充。原文自释“芤则血虚”，因血虚不能充盈脉道，故脉中空。血虚则诸经失养，可见胃络震动等症。"}], "n": {"主血虚": 1}, "a": {"11205": "主血虚"}, "t": 1, "np": 0}, "pc:关+涩+迟": {"o": "关·涩迟脉在古籍中从肝木太过不及立论，总属肝病脉象。其主病机可归为三类：肝实、肝虚与气逆。肝实者，脉实而弦，病在外，症见忘忽眩运、胁痛喜怒；肝虚者，脉虚而微，病在内，症见胸胁胀满；气逆者，脉沉而急，症见胁支满、小便难、头痛眼眩。三者皆以肝之平脉弦长为参照，涩迟之象提示气血运行不畅，或实或虚或逆，总不离肝木失调。临床当结合兼脉及症候，辨其虚实逆乱。", "c": [{"name": "主肝实", "desc": "原文指出脉实而弦为太过，病在外，令人忘忽眩运；肝实则两胁下引痛、喜怒。关部涩迟脉若兼实象，反映肝气实、气血壅滞，故主肝实之病机。"}], "n": {"主肝实": 1}, "a": {"19357": "主肝实"}, "t": 1, "np": 0}, "pc:双+弦+沉": {"o": "双·弦沉脉总起来主寒，以里寒内盛为核心，涵盖寒饮内结、寒凝心下、寒郁化热及寒实可下等具体病机。沉主里，弦主寒主饮，双弦强调寒邪深伏、脉气拘急。原文“寒脉沉弦，脉双弦者寒也”为总纲，其下诸段分别从寒饮、寒凝、寒郁化热、寒实等角度展开，均不离寒邪为患。各类之间相互关联：寒饮内结可致心下坚，寒凝日久可郁而化热，寒实内结则需下法。总体病机为寒邪深入千里，阳气被遏，或挟饮、或凝滞、或化热、或成实，治疗当以温散寒邪为要，兼以化饮、行气、泄实。", "c": [{"name": "主寒", "desc": "原文明言“寒脉沉弦，脉双弦者寒也”，弦脉如张弓弦、按之不移，为寒饮内结之象；沉主里，双弦强调寒邪深伏。寒邪客于里，阳气被遏，脉气紧张故弦，病机核心为里寒内盛。"}], "n": {"主寒": 1}, "a": {"21598": "主寒"}, "t": 1, "np": 0}, "pc:寸+沉+坚": {"o": "寸·沉坚脉总属里实内积之候。沉为病位在里，坚为邪气实结，二者相合，提示实邪深伏脏腑、气血凝滞不通。原文'寸口脉沉而坚者，病在中'一句，明确其病位不在表而在里，病性非虚而为实。与同段'浮而盛者病在外'相对，更显沉坚主内主实之定位。沉坚与沉紧、沉滑等脉同属沉类实脉，然坚脉尤重邪结之坚牢，故所主以里实、内积为核心。临床见此，当考虑积块、癥瘕、寒凝气滞等深痼之疾，治宜攻削消散，非轻浅之剂所能及。", "c": [{"name": "主里实", "desc": "脉沉而坚，沉主病位在里，坚为实邪内结之象。原文'寸口脉沉而坚者，病在中'，明言病位深在脏腑，非表浅之疾，故主里实积滞一类病机。"}], "n": {"主里实": 1}, "a": {"21803": "主里实"}, "t": 1, "np": 0}, "pc:寸+细+急": {"o": "寸·细急脉在古籍中虽仅一段论述，但结合尺部所见，其病机主要围绕下焦虚寒与筋脉拘急。细为阴血不足或阳气衰微，急为寒凝收引或筋脉挛急。原文以尺部细急为核心，兼及细微、虚小、弱等脉象，总归下焦阳气虚衰、寒从中生，故见溏泄冷利、足胫寒、痿痹脚疼；寒凝筋脉则见筋挛痹不能。三类病机相互关联：虚寒为根本，寒泄与筋挛痹为不同表现，前者偏于脏腑功能衰败，后者偏于经络筋脉拘急，均以细急脉为共同特征。", "c": [{"name": "主寒泄", "desc": "原文“尺脉细微，溏泄冷利”，又引《素问》“尺寒脉细，谓之后泄”。细急脉见于尺部，细为阴伤阳弱，急为寒凝收引，尺主下焦，故主下焦虚寒、泄泻冷利之证。"}], "n": {"主寒泄": 1}, "a": {"21807": "主寒泄"}, "t": 1, "np": 0}, "c:结+短": {"o": "短结脉总属气机郁结、脉道不畅之象。其核心病机为气结，多因情志内伤、脏气失调所致，尤与思伤脾、脾气郁结关系密切。原文以七情九气伤脏为纲，短脉独见于思伤脾，说明短结脉主要反映气机壅滞、脉气不伸的病理状态。气结则脉短，情志伤则脏气乱，脾病则运化失司，三者相互关联：情志伤为病因，脾病为病位，气结为病机关键。短结脉虽仅一脉，却提示气机郁滞、脏腑功能失调，临床当结合兼脉辨其病位与虚实。", "c": [{"name": "主气结", "desc": "思伤脾，气机郁结，脉道不畅，故脉短而气结。原文'过于思者伤于脾，故脉短而气结'，指出短脉由气结所致，气结则脉气不伸，故脉体短缩。"}], "n": {"主气结": 1}, "a": {"22819": "主气结"}, "t": 1, "np": 0}, "c:洪+疾": {"o": "洪疾脉总起来主邪热亢盛与虚阳浮越两类截然不同的病机，并可兼夹风热痰火及郁火气血虚等复杂情况。实热证中，洪为热盛气壅，疾为邪热急迫，可致躁烦，甚则热灼阴伤、阴液耗竭，形成正虚邪盛之危候；癫疾脉中洪大长疾又主风热痰火搏结，虚实夹杂。虚证中，洪大躁疾而空主虚阳浮越；弦洪疾脉则主郁火内燔兼气血两亏。各类之间，实热与虚阳浮越为洪疾脉的两大极端，风热痰火与郁火气血虚则为兼夹证候，临床须结合脉之有力无力及兼脉辨别虚实。", "c": [{"name": "主热盛烦躁", "desc": "洪脉主热盛，热扰心神则烦躁。原文“洪则躁烦”直接指出洪脉与躁烦并见，因热邪亢盛，内扰心神，故见烦躁不安。洪疾脉中洪为热盛气壅，疾为热势急迫，故主邪热亢盛之烦躁。"}], "n": {"主热盛烦躁": 1}, "a": {"22820": "主热盛烦躁"}, "t": 1, "np": 0}, "pc:关+沉+伏": {"o": "关部沉伏脉总起来主邪实内闭、脉道不畅之病机，可因热积深伏或痰气壅滞所致。热积者，热邪结于肠胃肝胆，阳气不达，脉反沉伏，按之劈劈应指，属实证；痰气者，痰浊与气交阻中焦，壅塞脉道，沉伏而或兼大，亦属邪实。二者虽病因不同，但均因实邪内闭、气血不畅而致沉伏，故沉伏非虚寒专属，须结合兼脉及症候辨其属热属痰。", "c": [{"name": "主热积内伏", "desc": "热邪深结肠胃或肝胆，壅遏气机，阳气不能外达，故脉沉伏；按之良久应指劈劈，为实热内闭之征，非虚寒可比。原文“热积内伏，脉反沉伏”及“沉伏非虚寒，而是实热内闭”明示此机。"}], "n": {"主热积内伏": 1}, "a": {"25067": "主热积内伏"}, "t": 1, "np": 0}, "pe:六+弱": {"o": "弱脉总以虚为核心，主气血不足、阳气衰微。其脉形沉细软弱，举按无力，示脉道不充、鼓动乏力。所主病机虽分气血两虚、脾胃虚寒、阳虚气陷、虚中夹痰瘀、虚火劳伤五类，然皆以正虚为枢：气血虚则脉弱不旺，脾胃虚则化源告竭，阳虚则气陷不升，虚而夹痰瘀则弱中兼滑涩，虚而阳浮则弱中见数。各段原文或见六部皆弱、或尺沉弱、或弱薄、或弱涩，皆不离虚字；其兼症虽异，而补益温敛之法相通。故弱脉为虚证之总脉，辨其兼象可别虚之所在与兼夹，然总以扶正为要。", "c": [{"name": "主气血两虚", "desc": "弱脉为气血不足、脉道不充之象。原文见六部皆弱、脉弱甚、六脉弱薄等，多伴四体羸尪、神情困倦、面黄肌瘦，示气血阴阳俱亏，故主气血两虚。"}, {"name": "主脾胃虚寒", "desc": "弱脉主中焦虚衰。原文见六脉弱薄而噎膈吐食、喜饮热汤、小便清白，或疟疾日久脉弱甚而断食吐涎，皆脾胃气绝、化源告竭之候，故主脾胃虚寒、中气衰败。"}, {"name": "主阳虚气陷", "desc": "弱脉兼尺沉弱、两尺尤甚，示下元阳气不充、命火式微。原文见泻下频频、泻后疼甚、过午发热夜半渐愈，为阳虚气陷、虚阳浮扰，故主阳虚气陷、脾肾不足。"}, {"name": "主虚中夹痰瘀", "desc": "弱脉主虚，兼滑则痰滞，兼涩则血瘀。原文见六部皆弱而右关滑，为心血不足、胃中有痰；或六部皆弱而两寸关兼涩，为中宫瘀滞。虚为本、痰瘀为标，故主虚中夹实。"}], "n": {"主气血两虚": 2, "主脾胃虚寒": 2, "主阳虚气陷": 1, "主虚中夹痰瘀": 3}, "a": {"2898": "主脾胃虚寒", "3090": "主气血两虚", "6237": "主虚中夹痰瘀", "6530": "主虚中夹痰瘀", "17413": "主脾胃虚寒", "18247": "主虚中夹痰瘀", "20554": "主阳虚气陷", "21797": "主气血两虚"}, "t": 8, "np": 0}, "pe:六+滑": {"o": "滑脉总以痰湿、热盛、血盛为核心病机，其脉往来流利，如珠走盘，主实邪内壅。痰湿内蕴则脉滑，热邪炽盛则滑而数洪，血盛充脉则滑而缓。滑脉兼浮主风痰，兼沉主里实积滞，兼弦主肝火痰湿，兼数主痰热，兼洪主热盛痰壅，兼缓主湿热。各类病机之间，痰湿与热常相合为患，血盛与湿热亦相关，里实积滞多兼痰热。滑脉总属阳脉，主实多虚少，然久病正伤亦可兼虚，如滑大无力主气虚。临证需结合兼脉及部位，辨痰湿、热、血盛、积滞之侧重。", "c": [{"name": "主痰湿", "desc": "滑脉往来流利，主痰湿内蕴。原文如右关略滑主中焦食积，左脉滑主血盛有孕，沉滑主里实痰浊积滞，皆以滑为痰湿之象。痰湿阻滞气机，脉道充盈而滑利，故滑脉为痰湿之核心脉象。"}, {"name": "主热", "desc": "滑脉兼数、洪、实等，主热盛。原文六脉微数示积热内蕴，数滑脉总属痰热湿火交结，滑洪脉主热盛痰湿壅阻，滑实脉主痰热壅盛。热邪内炽，脉道扩张，血行加速，故脉滑而数洪实。"}, {"name": "主血盛", "desc": "滑脉主血盛，多见于妇人经孕。原文左脉滑主血盛有孕，六脉缓滑示天癸将至、阴血充盈。血盛则脉道充溢，往来流利，故滑脉为血盛之征，尤见于冲任气血充盛之时。"}, {"name": "主里实积滞", "desc": "沉滑脉主里实痰浊积滞，包括食积、热毒内盛。原文右关略滑主中焦食积，沉滑主里有形实邪结聚。实邪内壅，气血不畅，脉沉而滑，故沉滑为里实积滞之象。"}, {"name": "主湿热", "desc": "滑缓脉主湿热血滞，气不下行。原文六脉缓滑，缓为脾湿，滑为挟热气不下行，气不下行则血上逆致齿衄。湿热内蕴，气血壅滞，脉缓滑并见，故主湿热之证。"}], "n": {"主痰湿": 1, "主热": 1, "主血盛": 1, "主里实积滞": 1, "主湿热": 2}, "a": {"3384": "主热", "3502": "主里实积滞", "6081": "主血盛", "6375": "主湿热", "14014": "主湿热", "21797": "主痰湿"}, "t": 6, "np": 0}, "pe:尺+和": {"o": "尺·和脉总起来主气血渐充、应时生发之象，亦可见于气血亏虚、肾阴不足及气聚为胀。其脉象以弦滑流利、弦而和、迟弱、细濡为特征，弦滑应春生之气，迟弱主营气不足，细濡主阴阳两亏。各类之间，应时生发与气聚为胀属生理或气机一时之变，非邪实；气血亏虚与肾阴不足则属虚损，需温养血气。尺部候肾，故虚证多关肾阴营血，而气聚为胀则因正气渐充、气机壅滞于气海，脉色和流，非痞非滞。总以脉证合参，辨其虚实，不可拘泥。", "c": [{"name": "主气血亏虚", "desc": "尺脉迟弱或细濡，迟主阳虚，弱主血少，细濡主气血亏虚。原文'尺脉迟弱为营气不足'及'脉象细焮尺濡'，素体瘦弱食少，天癸逾期，白带频下，皆因气血不足，冲任失养，尺部候肾，故显亏虚之象。"}, {"name": "主应时生发", "desc": "左尺弦滑流利，右尺弦而和，弦为春生之象，滑为气血流利。原文'立春在迩，宜乎左部之弦得'，说明弦非病脉，乃应时生发之气，脉色和流，故'非其痞也'，胀为正气聚于气海，非邪滞。"}], "n": {"主气血亏虚": 2, "主应时生发": 1}, "a": {"2988": "主应时生发", "3314": "主气血亏虚", "16043": "主气血亏虚"}, "t": 3, "np": 0}, "pe:尺+芤": {"o": "尺·芤脉总起来主下焦精血亏虚，并由此衍生出血虚、精亏、瘀血及心肾不交等病机。芤脉浮大中空，为血虚不能充脉之象，尺部候下焦，故首主血虚与精亏，此二者为病之本。精血既亏，脉道不充，血行滞涩，则可兼涩而致瘀血内结，此为本虚标实之变。若芤兼动，则下元精亏而心神浮越，心肾不能相交，终致精关不固，此为精亏神驰之果。四类病机以精血亏虚为核心，血虚、精亏为直接反映，瘀血为血虚滞涩之继发，心肾不交为精亏及神之演变，彼此关联，虚实相兼。", "c": [{"name": "主血虚", "desc": "芤脉浮大中空，如按葱管，为血虚不能充脉之象。尺部候下焦，尺芤则下元精血亏耗。原文虽未直引，但下属尺涩芤脉总述明言“芤脉浮大中空，主血虚”，且“尺脉芤涩，瘀血之诊”亦以芤示阴血亏虚、脉道不充，故尺芤首主血虚。"}], "n": {"主血虚": 1}, "a": {"21807": "主血虚"}, "t": 1, "np": 0}, "pc2:右关+数+滑": {"o": "右关数滑脉总属胃家实热痰湿之候。数主热，滑主痰湿，右关候脾胃，故其病机以湿热、痰实、积热三类为主。湿热者，偏于湿与热合流注经络；痰实者，偏于痰与热结聚胃家；积热者，偏于热与积滞壅塞肠胃。三者皆属实证、热证，病位在阳明胃与肠胃，可相互转化：湿郁化热则成湿热，痰热互结则为痰实，热积不散则成积热。原文或兼见脚气肿痛，或胁痛酸软，或腹痛便结，皆以右关滑数为辨证眼目，总不离痰湿热积壅滞中焦之机。", "c": [{"name": "主湿热", "desc": "右关数滑，数主热，滑主湿，湿热相合流注足阳明经。原文见脚软肿痛、发热饮冷、二便秘，薛氏断为足阳明经湿热流注，以大黄左经汤治之，故主湿热壅滞之证。"}, {"name": "主痰实", "desc": "右关滑数，滑为痰湿内蕴，数为热盛，痰与热结于胃家。原文谓“右关滑数，胃家痰实”，又云“脉滑而数，结痰热痰”，故主痰热实邪壅滞中焦，可见胁痛、酸软等症。"}, {"name": "主积热", "desc": "右关滑数，滑为热壅，数为热盛，热邪与积滞相结于肠胃。原文“右关滑数，肠胃积热”，并见热积内伏、腹痛便结，甚则脉反沉伏，按之劈劈，乃实热内闭之象，故主积热内结。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主湿热": 1, "主痰实": 2, "主积热": 1, "其他": 0}, "a": {"23594": "主湿热", "24673": "主痰实", "24977": "主痰实", "25067": "主积热"}, "t": 4, "np": 0}, "pc2:左关+弦+浮": {"o": "左关浮弦脉总起来主风邪与肝气不足，并可外见于中风。浮为风邪在表，弦主少阳厥阴风木，故浮弦相合，主风邪客于肝胆经络，如中风之脉左关浮弦，病在足厥阴、少阳；内伤自汗见左关浮弦，为挟风邪。又浮为不足，弦主肝病，故左关浮弦亦主肝气有损，属肝虚劳伤之脉。三类病机相互关联：风邪外中与肝气内损均可致浮弦，而中风之脉则是风邪中于经络的典型表现。", "c": [{"name": "主风邪", "desc": "浮为风邪在表，弦主少阳厥阴风木。左关浮弦，病在足厥阴、少阳，为风邪中于经络；内伤自汗见左关浮弦，为挟风邪，故加桂枝、白芍以疏风。"}, {"name": "主肝气损", "desc": "弦主肝病，浮为不足。左关浮弦，为肝气有损，属肝虚劳伤之脉，因浮主虚，弦主肝，合而示肝气不足。"}, {"name": "主中风", "desc": "中风之脉，左关浮弦，病在足厥阴、少阳。浮为风邪在表，弦主少阳厥阴风木，故中风见左关浮弦，示风邪中于肝胆经络。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主风邪": 1, "主肝气损": 1, "主中风": 1, "其他": 0}, "a": {"18419": "主风邪", "24606": "主中风", "24749": "主肝气损"}, "t": 3, "np": 0}, "pc2:左关+弦+细": {"o": "左关弦细脉总以肝为核心，主肝血不足、肝气郁结，并常兼他脏病机。弦为肝脉，细为血少，故单见弦细多责肝血亏虚、筋脉失养；若气机不畅则兼肝郁。若细甚而见他部细数，则为水亏火浮，肝火偏亢；若兼右关微数，则湿郁化热。若细主脾虚、左关弦主肝郁，则成脾虚肝郁之候。诸类之间，肝血不足与肝郁常互为因果；水亏火浮与湿郁化热可在阴虚基础上并存；脾虚肝郁则为肝木乘脾之变。总属本虚标实、虚实夹杂之脉。", "c": [{"name": "主肝血不足", "desc": "左关候肝，弦为肝脉，细为血少。原文如“左关独见弦细”伴肩痛不能屈伸，断为“肝血不荣于筋”；“脉细左关弦”兼“癸水未至、口渴跗浮”，亦属肝血虚少、筋脉失养。故弦细脉主肝血亏虚，筋脉失濡。"}, {"name": "主肝郁", "desc": "弦为肝气郁结之象，细为血虚。原文“左关弦”与“食入脘闷、脾泄”并见，断为肝郁乘脾；“左关细弦”伴“右腋间及腹中时觉窜痛”，窜痛为气郁之征。故弦细脉主肝气郁滞，疏泄失常。"}, {"name": "主水亏火浮", "desc": "细为水亏，弦为肝火。原文“左关细弦，右关微数，余部均细”，明言“细为水亏，弦为肝火”，症见耳鸣、足跟热痛、头晕、小泡，断为“水亏火浮”。故弦细脉主肾水亏虚、肝火浮越之上盛下虚证。"}, {"name": "主湿郁化热", "desc": "原文以“左关细弦，右关微数”合参，谓“数为湿郁化热”，症见耳鸣堵、足跟热痛、小泡、消化不速，断为“湿郁化热”。弦细脉在此与数脉并见，提示水亏火浮基础上兼湿郁化热，湿热内郁。"}, {"name": "主脾虚肝郁", "desc": "原文“脉细左关弦”，细主脾虚气血不足，弦主肝郁。症见“脾泄较差，食入脘闷”为脾虚不运，“癸水未至、口渴跗浮”为肝郁血虚、水湿不化。故弦细脉主脾虚肝郁，运化失职。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主肝血不足": 1, "主肝郁": 0, "主水亏火浮": 1, "主湿郁化热": 0, "主脾虚肝郁": 1, "其他": 0}, "a": {"9114": "主水亏火浮", "15014": "主肝血不足", "17070": "主脾虚肝郁"}, "t": 3, "np": 0}, "rs:沉取+散": {"o": "沉取散脉总起来主气机耗散、气阴两伤，兼及热盛伤气与脉气不敛。其核心病机为暑热或热邪耗伤气阴，气虚不能鼓动，阴伤不能充盈，故重按脉散若无，非真脉绝。原文三段落分别从暑伤气阴、脉象定义、阳暑热证展开：暑月自汗神疲、烦渴溺短、四肢逆冷，脉虚散重按若无，为气阴两伤、阳郁不达；阳暑热盛，火克金而伤气，脉洪滑或虚浮，为热盛伤气；脉象总汇中散脉形态为浮短而止，提示脉气涣散不敛。三类之间以气阴耗伤为共同基础，热盛为诱因，脉气不敛为表现，故散脉主虚、主热伤气，非主实寒或单纯阳虚，温补无功即其明证。", "c": [{"name": "主气阴两伤", "desc": "散脉重按若无，非脉绝，乃暑热耗气伤阴，气虚不能鼓动，阴伤不能充盈，故脉虚散无力。原文见暑月腹痛泄泻、自汗神疲、额汗溺短、烦渴、四肢逆冷，皆暑热耗气、阳郁不达之象，温补无功，正合气阴两伤之机。"}, {"name": "主热盛伤气", "desc": "阳暑酷热伤人，火能克金而热伤气，热盛则脉洪滑，气伤则脉虚浮。原文谓身热、头痛、烦躁、大渴、大汗、脉洪滑为阳证火盛；若汗出脉虚浮，为热伤气而气少，宜白虎加人参汤，说明热盛与气伤并存，散脉见于热伤气分。"}, {"name": "主脉象本形", "desc": "散脉作为脉象定义之一，指下形态为浮而短、短而止，或如散，与涩脉细迟往来难且散相类。原文脉象总汇中列散脉形态，旨在立脉名、明脉形，为辨病机之基础，故散脉本形主脉气涣散不敛，非专主一病。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主气阴两伤": 1, "主热盛伤气": 1, "主脉象本形": 1, "其他": 0}, "a": {"8324": "主气阴两伤", "21797": "主脉象本形", "23169": "主热盛伤气"}, "t": 3, "np": 0}});